#requires -Version 7.4
# Generated by DSR. Configuration is data; downloaded payloads are never executed.
# Requires PowerShell 7.4+ and Windows. Cooperating installers share a kernel lock.
[CmdletBinding()]
param(
    [string]$Version = '',
    [string]$Prefix = '',
    [string]$CacheDir = '',
    [switch]$Offline,
    [switch]$Recover,
    [switch]$FromSource,
    [switch]$AllowSourceBuild,
    [string]$SourceIfStale = '',
    [string]$SourceRef = '',
    [int]$SourceTimeout = 3600,
    [switch]$Yes,
    [switch]$Json,
    [switch]$Help
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$script:DsrWindowsInstallPolicyBase64 = '__DSR_WINDOWS_INSTALL_POLICY_B64__'
$script:DsrMaximumPayloadBytes = 2147483648L
$script:DsrMaximumExpandedBytes = 4294967296L

function Stop-DsrInstall {
    param([string]$Message, [int]$Code = 4, [switch]$TransientAcquisition, [int]$HttpStatus = 0)
    $failure = [System.InvalidOperationException]::new($Message)
    $failure.Data['DsrExitCode'] = $Code
    if ($TransientAcquisition) { $failure.Data['DsrTransientAcquisition'] = $true }
    if ($HttpStatus -gt 0) { $failure.Data['DsrHttpStatus'] = $HttpStatus }
    throw $failure
}

# Only acquisition callers may use this classification. Proof, cache, archive
# and executable failures never become permission to compile a different input.
function Test-DsrReleaseAcquisitionUnavailable {
    param([Exception]$Failure, [switch]$AllowMissing)
    if (-not $Failure.Data.Contains('DsrExitCode') -or $Failure.Data['DsrExitCode'] -ne 8) { return $false }
    if ($Failure.Data.Contains('DsrHttpStatus')) {
        $status = [int]$Failure.Data['DsrHttpStatus']
        # In particular, the older transient-API marker also covers 403. That
        # status may try public tag discovery, but never authorizes source.
        return $status -in @(408, 429) -or ($status -ge 500 -and $status -le 599) -or
            ($AllowMissing -and $status -in @(404, 410))
    }
    return $Failure.Data.Contains('DsrTransientAcquisition') -and
        $Failure.Data['DsrTransientAcquisition'] -eq $true
}

# PowerShell 7.4 uses .NET 8, whose HTTP exceptions distinguish unavailable
# transport from TLS, authentication, protocol and response-validation failures.
# Walk method-invocation wrappers as well; an unknown category is not permission
# to replace a verified release with a source build.
function Stop-DsrHttpTransportFailure {
    param([Exception]$Failure, [string]$Message, [bool]$DeadlineExpired)
    $pending = [Collections.Generic.Stack[Exception]]::new()
    $pending.Push($Failure)
    $classified = $false
    $unavailable = $true
    $cancelled = $false
    $stopped = $false
    while ($pending.Count -gt 0) {
        $current = $pending.Pop()
        if ($current -is [Management.Automation.PipelineStoppedException]) { $stopped = $true }
        if ($current -is [OperationCanceledException]) { $cancelled = $true }
        if ($current -is [Security.Authentication.AuthenticationException]) { $unavailable = $false }
        if ($current -is [Net.Http.HttpRequestException] -or $current -is [Net.Http.HttpIOException]) {
            $classified = $true
            if ($current.HttpRequestError -notin @(
                    [Net.Http.HttpRequestError]::NameResolutionError,
                    [Net.Http.HttpRequestError]::ConnectionError,
                    [Net.Http.HttpRequestError]::ResponseEnded) -or
                ($current -is [Net.Http.HttpRequestException] -and $null -ne $current.StatusCode)) {
                $unavailable = $false
            }
        }
        if ($current -is [AggregateException]) {
            # A combined failure has no single availability classification.
            $unavailable = $false
            foreach ($inner in $current.InnerExceptions) { $pending.Push($inner) }
        } elseif ($null -ne $current.InnerException) { $pending.Push($current.InnerException) }
    }
    if ($stopped -or ($cancelled -and -not $DeadlineExpired)) {
        Stop-DsrInstall 'GitHub acquisition was cancelled' 5
    }
    if ($cancelled -and $DeadlineExpired -and $unavailable) {
        Stop-DsrInstall 'GitHub acquisition exceeded its complete-transfer deadline' 8 -TransientAcquisition
    }
    # Messages are supplied by the caller, never derived from exception text,
    # which can contain credentials or signed object-storage URLs.
    Stop-DsrInstall $Message 8 -TransientAcquisition:($classified -and $unavailable)
}

function Write-DsrInstallLog {
    param([string]$Message)
    [Console]::Error.WriteLine('[dsr installer] ' + $Message)
}

function Write-DsrInstallVerbose {
    param([string]$Message)
    if ($VerbosePreference -eq [Management.Automation.ActionPreference]::Continue) { Write-DsrInstallLog $Message }
}

function Test-DsrName {
    param($Value)
    return $Value -is [string] -and $Value -cmatch '^[A-Za-z0-9][A-Za-z0-9._+-]{0,239}$' -and
        -not $Value.Contains('..')
}

function Test-DsrWindowsName {
    param($Value)
    return (Test-DsrName $Value) -and -not $Value.EndsWith('.') -and
        $Value -inotmatch '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)'
}

function Assert-DsrFields {
    param($Value, [string[]]$Required, [string[]]$Optional = @())
    if ($Value -isnot [System.Collections.IDictionary]) { Stop-DsrInstall 'Expected a JSON object' }
    foreach ($name in $Required) {
        if (-not $Value.Contains($name)) { Stop-DsrInstall ('Missing policy field: ' + $name) }
    }
    foreach ($name in $Value.Keys) {
        if ($name -cnotin $Required -and $name -cnotin $Optional) {
            Stop-DsrInstall ('Unknown policy field: ' + $name)
        }
    }
}

function Assert-DsrJsonKeys {
    param([System.Text.Json.JsonElement]$Element)
    if ($Element.ValueKind -eq [System.Text.Json.JsonValueKind]::Object) {
        $names = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($property in $Element.EnumerateObject()) {
            if (-not $names.Add($property.Name)) { Stop-DsrInstall 'Duplicate JSON key' }
            Assert-DsrJsonKeys $property.Value
        }
    } elseif ($Element.ValueKind -eq [System.Text.Json.JsonValueKind]::Array) {
        foreach ($item in $Element.EnumerateArray()) { Assert-DsrJsonKeys $item }
    }
}

function ConvertFrom-DsrJson {
    param([string]$Text)
    $document = $null
    try {
        $document = [System.Text.Json.JsonDocument]::Parse($Text)
        Assert-DsrJsonKeys $document.RootElement
        # Keep empty and singleton API pages as arrays. PowerShell's normal
        # pipeline enumeration would turn [] into null and [row] into row.
        return ,(ConvertFrom-Json -InputObject $Text -AsHashtable -Depth 64 -NoEnumerate)
    } finally {
        if ($null -ne $document) { $document.Dispose() }
    }
}

function Get-DsrBytesHash {
    param([byte[]]$Bytes)
    return [Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData($Bytes)).ToLowerInvariant()
}

function Get-DsrInstallPolicy {
    $bytes = [Convert]::FromBase64String($script:DsrWindowsInstallPolicyBase64)
    if ($bytes.Length -eq 0 -or $bytes.Length -gt 1048576) { Stop-DsrInstall 'Invalid embedded installer policy size' }
    $encoding = [System.Text.UTF8Encoding]::new($false, $true)
    $policy = ConvertFrom-DsrJson $encoding.GetString($bytes)
    Assert-DsrFields $policy @('schema_version', 'tool', 'repo', 'binary_name', 'public_key', 'platforms') @('source')
    if (($policy.schema_version -isnot [long] -and $policy.schema_version -isnot [int]) -or
        $policy.schema_version -ne 1 -or -not (Test-DsrName $policy.tool) -or
        -not (Test-DsrName $policy.binary_name) -or $policy.repo -isnot [string] -or
        $policy.repo -cnotmatch '^[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*$' -or
        $policy.public_key -isnot [string] -or
        $policy.platforms -isnot [System.Collections.IDictionary] -or $policy.platforms.Count -lt 1) {
        Stop-DsrInstall 'Invalid embedded Windows installer policy'
    }
    if ($policy.Contains('source')) { Assert-DsrSourcePolicy $policy.source }
    if ($policy.public_key) {
        if ($policy.public_key -cnotmatch '^[A-Za-z0-9+/]{56}$' -or
            [Convert]::FromBase64String($policy.public_key).Length -ne 42) {
            Stop-DsrInstall 'Invalid embedded Minisign public key'
        }
    }
    foreach ($platform in $policy.platforms.Keys) {
        if ($platform -cnotin @('windows/amd64', 'windows/arm64', 'windows/386')) {
            Stop-DsrInstall ('Unsupported configured Windows platform: ' + $platform)
        }
        $selection = $policy.platforms[$platform]
        Assert-DsrFields $selection @('name', 'format', 'binaries', 'target_triple')
        if ($selection.name -isnot [string] -or
            -not (Test-DsrWindowsName $selection.name.Replace('${version}', '1.2.3')) -or
            $selection.format -cnotin @('zip', 'tar.gz', 'none') -or
            $selection.binaries -isnot [array] -or $selection.binaries.Count -lt 1 -or
            $selection.binaries.Count -gt 64 -or $selection.target_triple -isnot [string] -or
            ($selection.target_triple -and -not (Test-DsrName $selection.target_triple))) {
            Stop-DsrInstall ('Invalid Windows payload selection: ' + $platform)
        }
        if ($selection.format -ceq 'none' -and $selection.binaries.Count -ne 1) {
            Stop-DsrInstall 'A raw Windows payload must select exactly one executable'
        }
        $names = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($name in $selection.binaries) {
            if (-not (Test-DsrWindowsName $name) -or $name.Length -gt 200 -or
                -not $name.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase) -or
                -not $names.Add($name)) { Stop-DsrInstall 'Invalid or colliding Windows executable family' }
        }
        $primary = $policy.binary_name
        if (-not $primary.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase)) { $primary += '.exe' }
        if (-not $names.Contains($primary)) { Stop-DsrInstall 'Executable family does not include its primary binary' }
    }
    return @{ value = $policy; sha256 = (Get-DsrBytesHash $bytes) }
}

function Get-DsrHostPlatform {
    if (-not [System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        Stop-DsrInstall 'This installer requires native Windows and PowerShell 7.4 or newer' 3
    }
    switch ([System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture.ToString()) {
        'X64' { return 'windows/amd64' }
        'Arm64' { return 'windows/arm64' }
        'X86' { return 'windows/386' }
        default { Stop-DsrInstall 'Unsupported native Windows architecture' 3 }
    }
}

function Get-DsrPlainPath {
    param([string]$Path, [switch]$Directory, [switch]$File, [switch]$AllowRoot)
    if (-not $Path -or -not [IO.Path]::IsPathFullyQualified($Path) -or
        $Path -match '[\x00-\x1f\x7f]' -or $Path -match '(^|[\\/])\.{1,2}([\\/]|$)' -or
        $Path.StartsWith('\\') -or $Path.StartsWith('//')) {
        Stop-DsrInstall 'Use an absolute local path without dot components or control characters'
    }
    $canonical = [IO.Path]::GetFullPath($Path)
    $full = $canonical.TrimEnd([IO.Path]::DirectorySeparatorChar, [IO.Path]::AltDirectorySeparatorChar)
    if (-not $full -or $full -eq [IO.Path]::GetPathRoot($canonical).TrimEnd('\', '/')) {
        if (-not $AllowRoot) { Stop-DsrInstall 'A filesystem root cannot be an installer destination' }
        $full = [IO.Path]::GetPathRoot($canonical)
    }
    $cursor = $full
    while ($cursor) {
        try { $attributes = [IO.File]::GetAttributes($cursor) }
        catch [IO.FileNotFoundException] { $attributes = $null }
        catch [IO.DirectoryNotFoundException] { $attributes = $null }
        if ($null -ne $attributes) {
            if (($attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-DsrInstall 'A selected path contains a link or reparse point' 7 }
            if ($cursor -ne $full -and ($attributes -band [IO.FileAttributes]::Directory) -eq 0) {
                Stop-DsrInstall 'A selected path contains a non-directory ancestor' 7
            }
        }
        $next = [IO.Path]::GetDirectoryName($cursor)
        if ($next -eq $cursor) { break }
        $cursor = $next
    }
    if ($Directory -and -not [IO.Directory]::Exists($full)) { Stop-DsrInstall 'Required directory is missing' 7 }
    if ($File -and -not [IO.File]::Exists($full)) { Stop-DsrInstall 'Required regular file is missing' 7 }
    return $full
}

function Test-DsrPathsOverlap {
    param([string]$Left, [string]$Right)
    $separator = [IO.Path]::DirectorySeparatorChar
    return $Left.Equals($Right, [StringComparison]::OrdinalIgnoreCase) -or
        $Left.StartsWith($Right + $separator, [StringComparison]::OrdinalIgnoreCase) -or
        $Right.StartsWith($Left + $separator, [StringComparison]::OrdinalIgnoreCase)
}

function New-DsrPrivateDirectory {
    param([string]$Path)
    $pathValue = Get-DsrPlainPath $Path
    if ([IO.Directory]::Exists($pathValue) -or [IO.File]::Exists($pathValue)) { Stop-DsrInstall 'Private staging path already exists' 2 }
    $parent = [IO.Path]::GetDirectoryName($pathValue)
    $null = Get-DsrPlainPath $parent -Directory -AllowRoot
    if ([System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User
        $acl = [Security.AccessControl.DirectorySecurity]::new()
        $acl.SetOwner($sid)
        $acl.SetAccessRuleProtection($true, $false)
        $rule = [Security.AccessControl.FileSystemAccessRule]::new($sid, [Security.AccessControl.FileSystemRights]::FullControl,
            [Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit',
            [Security.AccessControl.PropagationFlags]::None, [Security.AccessControl.AccessControlType]::Allow)
        $acl.AddAccessRule($rule)
        [IO.FileSystemAclExtensions]::Create([IO.DirectoryInfo]::new($pathValue), $acl)
    } else {
        # This branch permits genuine PowerShell integration tests on POSIX;
        # Get-DsrHostPlatform still rejects non-Windows production execution.
        $null = [IO.Directory]::CreateDirectory($pathValue)
        [IO.File]::SetUnixFileMode($pathValue, [IO.UnixFileMode]'UserRead,UserWrite,UserExecute')
    }
    return Get-DsrPlainPath $pathValue -Directory
}

function New-DsrDirectoryChain {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path
    if ([IO.Directory]::Exists($full)) { return $full }
    $pending = [Collections.Generic.List[string]]::new()
    $cursor = $full
    while (-not [IO.Directory]::Exists($cursor)) {
        $pending.Add($cursor)
        $cursor = [IO.Path]::GetDirectoryName($cursor)
        if (-not $cursor) { Stop-DsrInstall 'Missing filesystem root' }
    }
    for ($index = $pending.Count - 1; $index -ge 0; $index--) {
        $null = New-DsrPrivateDirectory $pending[$index]
    }
    return Get-DsrPlainPath $full -Directory
}

function New-DsrPrivateFile {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path
    $null = Get-DsrPlainPath ([IO.Path]::GetDirectoryName($full)) -Directory -AllowRoot
    if ([System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        # Elevated Windows tokens can default a new file's owner to the
        # Administrators group. Set the exact user and private ACL atomically
        # at CreateNew, preserving strict ownership checks on existing cache.
        $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User
        $acl = [Security.AccessControl.FileSecurity]::new()
        $acl.SetOwner($sid)
        $acl.SetAccessRuleProtection($true, $false)
        $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,
            [Security.AccessControl.FileSystemRights]::FullControl, [Security.AccessControl.AccessControlType]::Allow))
        return [IO.FileSystemAclExtensions]::Create([IO.FileInfo]::new($full), [IO.FileMode]::CreateNew,
            [Security.AccessControl.FileSystemRights]::FullControl, [IO.FileShare]::None, 4096,
            [IO.FileOptions]::None, $acl)
    }
    # The POSIX integration adapter exercises exclusive private creation too;
    # it does not substitute or qualify the Windows owner/ACL implementation.
    $options = [IO.FileStreamOptions]::new()
    $options.Mode = [IO.FileMode]::CreateNew
    $options.Access = [IO.FileAccess]::ReadWrite
    $options.Share = [IO.FileShare]::None
    $options.UnixCreateMode = [IO.UnixFileMode]'UserRead,UserWrite'
    return [IO.FileStream]::new($full, $options)
}

function Assert-DsrCacheCustody {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path
    if ([System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        $current = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
        $trusted = @($current, 'S-1-5-18', 'S-1-5-32-544',
            'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464')
        $cursor = $full
        $selected = $true
        while ($cursor) {
            $item = if ([IO.Directory]::Exists($cursor)) { [IO.DirectoryInfo]::new($cursor) } else { [IO.FileInfo]::new($cursor) }
            $acl = [IO.FileSystemAclExtensions]::GetAccessControl($item)
            $owner = $acl.GetOwner([Security.Principal.SecurityIdentifier]).Value
            if (($selected -and $owner -cne $current) -or (-not $selected -and $owner -cnotin $trusted)) {
                Stop-DsrInstall 'Download cache ownership is not private to the current user' 7
            }
            $descriptor = [Security.AccessControl.RawSecurityDescriptor]::new($acl.GetSecurityDescriptorBinaryForm(), 0)
            if ($null -eq $descriptor.DiscretionaryAcl) { Stop-DsrInstall 'Download cache has an unrestricted access list' 7 }
            foreach ($rule in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
                if ($rule.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow -or
                    ($rule.PropagationFlags -band [Security.AccessControl.PropagationFlags]::InheritOnly) -ne 0 -or
                    $rule.IdentityReference.Value -cin $trusted) { continue }
                # Ancestors may permit creating unrelated names, but must not
                # permit replacing this cache directory or rewriting its ACL.
                $mask = [long][Security.AccessControl.FileSystemRights]'Delete,DeleteSubdirectoriesAndFiles,ChangePermissions,TakeOwnership'
                if ($selected) { $mask = $mask -bor [long][Security.AccessControl.FileSystemRights]'Write,Delete' }
                if (([long]$rule.FileSystemRights -band $mask) -ne 0) {
                    Stop-DsrInstall 'Download cache permits modification by another principal' 7
                }
            }
            $selected = $false
            $next = [IO.Path]::GetDirectoryName($cursor)
            if ($next -eq $cursor) { break }
            $cursor = $next
        }
    } else {
        # Only reached by the explicit POSIX integration-test host adapter.
        # Native execution is guarded by Get-DsrHostPlatform.
        $mode = [IO.File]::GetUnixFileMode($full)
        $foreignWrites = [IO.UnixFileMode]'GroupWrite,OtherWrite'
        if (($mode -band $foreignWrites) -ne 0) { Stop-DsrInstall 'Download cache is writable by other users' 7 }
    }
}

function Open-DsrReadFile {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path -File
    return [IO.FileStream]::new($full, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
}

function Get-DsrFileEvidence {
    param([string]$Path)
    $stream = Open-DsrReadFile $Path
    try {
        $size = $stream.Length
        $hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream)).ToLowerInvariant()
        if ($stream.Length -ne $size) { Stop-DsrInstall 'File size changed during verification' 7 }
        return @{ sha256 = $hash; size_bytes = $size }
    } finally { $stream.Dispose() }
}

function Read-DsrTextFile {
    param([string]$Path, [long]$Limit = 8388608)
    $stream = Open-DsrReadFile $Path
    try {
        if ($stream.Length -gt $Limit) { Stop-DsrInstall 'Metadata exceeds its size limit' 7 }
        $reader = [IO.StreamReader]::new($stream, [Text.UTF8Encoding]::new($false, $true), $true, 4096, $true)
        try { return $reader.ReadToEnd() } finally { $reader.Dispose() }
    } finally { $stream.Dispose() }
}

function Write-DsrNewTextFile {
    param([string]$Path, [string]$Text)
    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($Text)
    $stream = New-DsrPrivateFile $Path
    try { $stream.Write($bytes, 0, $bytes.Length); $stream.Flush($true) } finally { $stream.Dispose() }
}

function Copy-DsrNewFile {
    param([string]$Source, [string]$Destination)
    $incoming = Open-DsrReadFile $Source
    try {
        $outgoing = New-DsrPrivateFile $Destination
        try { $incoming.CopyTo($outgoing); $outgoing.Flush($true) } finally { $outgoing.Dispose() }
    } finally { $incoming.Dispose() }
}

function Remove-DsrPrivateTree {
    param([string]$Path)
    if (-not $Path -or -not [IO.Directory]::Exists($Path)) { return }
    $null = Get-DsrPlainPath $Path -Directory
    foreach ($entry in [IO.DirectoryInfo]::new($Path).EnumerateFileSystemInfos()) {
        if (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
            Stop-DsrInstall ('Private staging changed; retained for inspection: ' + $Path) 7
        }
        if (($entry.Attributes -band [IO.FileAttributes]::Directory) -ne 0) { Remove-DsrPrivateTree $entry.FullName }
        else { [IO.File]::Delete($entry.FullName) }
    }
    [IO.Directory]::Delete($Path, $false)
}

function Get-DsrGitHubToken {
    foreach ($variable in @('DSR_GH_TOKEN', 'GITHUB_TOKEN', 'GH_TOKEN')) {
        $candidate = [Environment]::GetEnvironmentVariable($variable)
        if ($candidate) {
            if ($candidate -match '[\x00-\x20\x7f]') { Stop-DsrInstall 'Invalid selected GitHub credential' 4 }
            return $candidate
        }
    }
    return ''
}

function New-DsrHttpClient {
    $handler = [Net.Http.HttpClientHandler]::new()
    $handler.AllowAutoRedirect = $false
    $handler.UseCookies = $false
    # Disposing this client also disposes its exclusively owned handler.
    $client = [Net.Http.HttpClient]::new($handler, $true)
    $client.Timeout = [Threading.Timeout]::InfiniteTimeSpan
    return $client
}

function Invoke-DsrDownload {
    param([string]$Url, [string]$Destination, [switch]$Optional, [long]$MaximumBytes = 2147483648,
          [switch]$ApiAsset, [switch]$SourceMetadata)
    $uri = [Uri]$Url
    if ($uri.Scheme -cne 'https' -or $uri.Host -cnotin @('github.com', 'api.github.com') -or
        -not $uri.IsDefaultPort -or $uri.UserInfo -or $uri.Fragment) {
        Stop-DsrInstall 'Invalid GitHub acquisition URL' 4
    }
    if ($ApiAsset -and ($uri.Host -cne 'api.github.com' -or
        $uri.AbsolutePath -cnotmatch '^/repos/[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*/releases/assets/[1-9][0-9]*$')) {
        Stop-DsrInstall 'Invalid GitHub release-asset API URL' 4
    }
    $token = Get-DsrGitHubToken
    $apiPrefix = ''
    if ($SourceMetadata) {
        if ($ApiAsset -or $Optional -or $uri.Host -cne 'api.github.com' -or
            $uri.AbsolutePath -cnotmatch '^(/repos/[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*/)(commits|commits/tags%2[Ff][A-Za-z0-9._+%\-]+|compare/[0-9a-f]{40}(?:[0-9a-f]{24})?\.\.\.[0-9a-f]{40}(?:[0-9a-f]{24})?)$') {
            Stop-DsrInstall 'Invalid GitHub source-freshness API scope' 4
        }
        $apiPrefix = $Matches[1]
        $route = $Matches[2]
        if (($route.StartsWith('commits/tags', [StringComparison]::Ordinal) -and $uri.Query) -or
            (-not $route.StartsWith('commits/tags', [StringComparison]::Ordinal) -and $uri.Query -cne '?per_page=1')) {
            Stop-DsrInstall 'Invalid GitHub source-freshness query' 4
        }
    } elseif ($uri.Host -ceq 'api.github.com') {
        if ($uri.AbsolutePath -cnotmatch '^(/repos/[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*/releases/)') {
            Stop-DsrInstall 'Invalid GitHub release API scope' 4
        }
        $apiPrefix = $Matches[1]
    }
    $client = New-DsrHttpClient
    $deadline = [Threading.CancellationTokenSource]::new([TimeSpan]::FromSeconds(60))
    $sendCredential = [bool]$apiPrefix
    try {
        for ($redirect = 0; $redirect -le 5; $redirect++) {
            $request = [Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Get, $uri)
            $request.Headers.UserAgent.ParseAdd('doodlestein_self_releaser-installer/1.0')
            $accept = if ($ApiAsset) { 'application/octet-stream' } else { 'application/vnd.github+json' }
            $request.Headers.Accept.ParseAdd($accept)
            $null = $request.Headers.TryAddWithoutValidation('X-GitHub-Api-Version', '2022-11-28')
            # Credentials belong only to the configured repository's API
            # requests, never browser URLs or signed object-storage redirects.
            if ($token -and $sendCredential) {
                $request.Headers.Authorization = [Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer', $token)
            }
            $response = $null
            try {
                $response = $client.SendAsync($request, [Net.Http.HttpCompletionOption]::ResponseHeadersRead,
                    $deadline.Token).GetAwaiter().GetResult()
                $status = [int]$response.StatusCode
                if ($status -in @(301, 302, 303, 307, 308)) {
                    if ($SourceMetadata) { Stop-DsrInstall 'Source freshness cannot follow redirects' 8 }
                    if ($redirect -eq 5 -or $null -eq $response.Headers.Location) { Stop-DsrInstall 'Invalid or excessive download redirects' 8 }
                    $uri = [Uri]::new($uri, $response.Headers.Location)
                    if ($uri.Scheme -cne 'https' -or -not $uri.IsDefaultPort -or $uri.UserInfo -or $uri.Fragment) {
                        Stop-DsrInstall 'Refusing an unsafe download redirect' 8
                    }
                    if ($apiPrefix) {
                        $sameScope = $uri.Host -ceq 'api.github.com' -and
                            $uri.AbsolutePath.StartsWith($apiPrefix, [StringComparison]::Ordinal)
                        if ((-not $ApiAsset -or $uri.Host -ceq 'api.github.com') -and -not $sameScope) {
                            Stop-DsrInstall 'GitHub API redirect changed the selected repository' 8
                        }
                        # Once a request leaves the API scope, a redirect back
                        # cannot regain the original Authorization header.
                        $sendCredential = $sendCredential -and $sameScope
                    }
                    continue
                }
                if ($status -in @(404, 410) -and $Optional) { return $false }
                if ($status -ne 200) {
                    Stop-DsrInstall ('GitHub download failed with HTTP ' + $status) 8 -HttpStatus $status `
                        -TransientAcquisition:($status -in @(403, 408, 429) -or ($status -ge 500 -and $status -le 599))
                }
                if ($null -ne $response.Content.Headers.ContentLength -and $response.Content.Headers.ContentLength -gt $MaximumBytes) {
                    Stop-DsrInstall 'Download exceeds its size limit' 7
                }
                $incoming = $response.Content.ReadAsStreamAsync($deadline.Token).GetAwaiter().GetResult()
                try {
                    $outgoing = New-DsrPrivateFile $Destination
                    try {
                        $buffer = [byte[]]::new(1048576)
                        $total = 0L
                        while (($count = $incoming.ReadAsync($buffer, 0, $buffer.Length, $deadline.Token).GetAwaiter().GetResult()) -gt 0) {
                            $total += $count
                            if ($total -gt $MaximumBytes) { Stop-DsrInstall 'Download exceeds its size limit' 7 }
                            $outgoing.Write($buffer, 0, $count)
                        }
                        $outgoing.Flush($true)
                    } finally { $outgoing.Dispose() }
                } finally { $incoming.Dispose() }
                return $true
            } finally {
                if ($null -ne $response) { $response.Dispose() }
                $request.Dispose()
            }
        }
    } catch [OperationCanceledException], [Net.Http.HttpRequestException], [Net.Http.HttpIOException] {
        Stop-DsrHttpTransportFailure $_.Exception 'GitHub download failed during HTTPS transport' $deadline.IsCancellationRequested
    } finally { $deadline.Dispose(); $client.Dispose(); $token = '' }
    Stop-DsrInstall 'Download did not complete' 8
}

# Resolve the observed default branch and annotated release tag to immutable
# commits before comparing. A paginated commit list is not a distance count.
# Match Bash's strict threshold and ancestral-history contract: incomplete,
# denied, malformed or divergent metadata is unknown, never source consent.
function Get-DsrReleaseFreshness {
    param([string]$Repository, [string]$Tag, [int]$Threshold, [string]$Directory)
    $unknown = @{ status = 'unknown'; repository = $Repository; release_version = $Tag;
        threshold = $Threshold; reason = 'freshness metadata unavailable or invalid' }
    $api = 'https://api.github.com/repos/' + $Repository
    try {
        $root = New-DsrPrivateDirectory ([IO.Path]::Combine($Directory, 'freshness'))
        $path = [IO.Path]::Combine($root, 'head.json')
        $null = Invoke-DsrDownload ($api + '/commits?per_page=1') $path -SourceMetadata -MaximumBytes 8388608
        $heads = ConvertFrom-DsrJson (Read-DsrTextFile $path)
        if ($heads -isnot [array] -or $heads.Count -ne 1 -or
            $heads[0] -isnot [System.Collections.IDictionary] -or -not $heads[0].Contains('sha') -or
            $heads[0].sha -isnot [string] -or $heads[0].sha -cnotmatch '^([0-9a-f]{40}|[0-9a-f]{64})$') { return $unknown }
        $head = $heads[0].sha
        $path = [IO.Path]::Combine($root, 'base.json')
        $null = Invoke-DsrDownload ($api + '/commits/' + [Uri]::EscapeDataString('tags/' + $Tag)) $path -SourceMetadata -MaximumBytes 8388608
        $baseRow = ConvertFrom-DsrJson (Read-DsrTextFile $path)
        if ($baseRow -isnot [System.Collections.IDictionary] -or -not $baseRow.Contains('sha') -or
            $baseRow.sha -isnot [string] -or $baseRow.sha -cnotmatch '^([0-9a-f]{40}|[0-9a-f]{64})$') { return $unknown }
        $base = $baseRow.sha
        $path = [IO.Path]::Combine($root, 'compare.json')
        $null = Invoke-DsrDownload ($api + '/compare/' + $base + '...' + $head + '?per_page=1') $path -SourceMetadata -MaximumBytes 8388608
        $comparison = ConvertFrom-DsrJson (Read-DsrTextFile $path)
        if ($comparison -isnot [System.Collections.IDictionary]) { return $unknown }
        foreach ($name in @('ahead_by', 'behind_by', 'total_commits')) {
            if (-not $comparison.Contains($name) -or
                ($comparison[$name] -isnot [long] -and $comparison[$name] -isnot [int]) -or
                $comparison[$name] -lt 0 -or $comparison[$name] -gt 1000000000) { return $unknown }
        }
        foreach ($name in @('base_commit', 'merge_base_commit')) {
            if (-not $comparison.Contains($name) -or $comparison[$name] -isnot [System.Collections.IDictionary] -or
                -not $comparison[$name].Contains('sha') -or $comparison[$name].sha -isnot [string] -or
                $comparison[$name].sha -cne $base) { return $unknown }
        }
        if (-not $comparison.Contains('status') -or $comparison.status -isnot [string] -or
            $comparison.behind_by -ne 0 -or $comparison.total_commits -ne $comparison.ahead_by -or
            ($head -ceq $base -and ($comparison.status -cne 'identical' -or $comparison.ahead_by -ne 0)) -or
            ($head -cne $base -and ($comparison.status -cne 'ahead' -or $comparison.ahead_by -le 0))) { return $unknown }
        return @{ status = $(if ($comparison.ahead_by -gt $Threshold) { 'stale' } else { 'fresh' });
            repository = $Repository; release_version = $Tag; release_commit = $base; head_commit = $head;
            commits_behind = $comparison.ahead_by; threshold = $Threshold }
    } catch {
        $failure = $_.Exception
        while ($null -ne $failure) {
            if ($failure -is [OperationCanceledException] -or
                $failure -is [Management.Automation.PipelineStoppedException] -or
                ($failure.Data.Contains('DsrExitCode') -and $failure.Data['DsrExitCode'] -eq 5)) {
                $_.Exception.Data['DsrExitCode'] = 5
                throw
            }
            $failure = $failure.InnerException
        }
        # Transport exceptions may contain URLs. Keep the public decision
        # stable and credential-free; none of these failures may start Git.
        return $unknown
    }
}

# GitHub's public latest-release redirect does not consume the REST API rate
# budget. Resolve only that repository's exact tag route with bounded HEAD
# requests; never scrape HTML or send a credential to the browser endpoint.
function Get-DsrPublicLatestTag {
    param([string]$Repository)
    $latestPath = '/' + $Repository + '/releases/latest'
    $tagPrefix = '/' + $Repository + '/releases/tag/'
    $uri = [Uri]('https://github.com' + $latestPath)
    $client = New-DsrHttpClient
    $deadline = [Threading.CancellationTokenSource]::new([TimeSpan]::FromSeconds(60))
    try {
        for ($redirect = 0; $redirect -le 5; $redirect++) {
            # Validate every destination before contacting it, including a
            # relative Location resolved against the previous request URL.
            if ($uri.Scheme -cne 'https' -or $uri.Host -cne 'github.com' -or
                -not $uri.IsDefaultPort -or $uri.UserInfo -or $uri.Query -or $uri.Fragment) {
                Stop-DsrInstall 'Refusing an unsafe public latest-release redirect' 8
            }
            $tag = ''
            if ($uri.AbsolutePath.StartsWith($tagPrefix, [StringComparison]::Ordinal)) {
                $tag = [Uri]::UnescapeDataString($uri.AbsolutePath.Substring($tagPrefix.Length))
                if (-not (Test-DsrName $tag) -or $tag -match '[\x00-\x20\x7f]') {
                    Stop-DsrInstall 'Public latest-release redirect does not select a safe exact tag' 8
                }
            } elseif ($uri.AbsolutePath -cne $latestPath) {
                Stop-DsrInstall 'Public latest-release redirect changed the selected repository or route' 8
            }
            $request = [Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Head, $uri)
            $request.Headers.UserAgent.ParseAdd('doodlestein_self_releaser-installer/1.0')
            $response = $null
            try {
                $response = $client.SendAsync($request, [Net.Http.HttpCompletionOption]::ResponseHeadersRead,
                    $deadline.Token).GetAwaiter().GetResult()
                $status = [int]$response.StatusCode
                if ($status -in @(301, 302, 303, 307, 308)) {
                    if ($redirect -eq 5 -or $null -eq $response.Headers.Location) {
                        Stop-DsrInstall 'Invalid or excessive public latest-release redirects' 8
                    }
                    $uri = [Uri]::new($uri, $response.Headers.Location)
                    continue
                }
                if ($status -ne 200 -or -not $tag) {
                    Stop-DsrInstall 'Cannot resolve the latest published release; use -Version with an existing tag' 8 -HttpStatus $status
                }
                return $tag
            } finally {
                if ($null -ne $response) { $response.Dispose() }
                $request.Dispose()
            }
        }
    } catch [OperationCanceledException], [Net.Http.HttpRequestException], [Net.Http.HttpIOException] {
        Stop-DsrHttpTransportFailure $_.Exception 'Public latest-release discovery failed during HTTPS transport; use -Version with an existing tag' $deadline.IsCancellationRequested
    } finally { $deadline.Dispose(); $client.Dispose() }
    Stop-DsrInstall 'Public latest-release discovery did not complete' 8
}

function Assert-DsrReleaseIdentity {
    param($Release, [string]$Tag)
    if ($Release -isnot [System.Collections.IDictionary] -or
        -not $Release.Contains('id') -or ($Release.id -isnot [long] -and $Release.id -isnot [int]) -or
        $Release.id -le 0 -or -not $Release.Contains('tag_name') -or $Release.tag_name -isnot [string] -or
        $Release.tag_name -cne $Tag -or
        -not $Release.Contains('draft') -or $Release.draft -isnot [bool] -or $Release.draft) {
        Stop-DsrInstall 'GitHub release identity does not match the selected published tag' 7
    }
}

function Get-DsrReleaseAssets {
    param([string]$Repository, [long]$ReleaseId, [string]$Directory)
    $assets = [Collections.Generic.Dictionary[string, object]]::new([StringComparer]::Ordinal)
    $ids = [Collections.Generic.HashSet[long]]::new()
    # Construct every page URL ourselves. Neither server-supplied URLs nor
    # Link headers can change repository/host or carry credentials elsewhere.
    for ($page = 1; $page -le 101; $page++) {
        $path = [IO.Path]::Combine($Directory, ('release-assets-' + $page + '.json'))
        $url = 'https://api.github.com/repos/' + $Repository + '/releases/' + $ReleaseId + '/assets?per_page=100&page=' + $page
        $null = Invoke-DsrDownload $url $path -MaximumBytes 8388608
        $rows = ConvertFrom-DsrJson (Read-DsrTextFile $path)
        if ($rows -isnot [array] -or $rows.Count -gt 100) { Stop-DsrInstall 'Malformed GitHub release asset page' 7 }
        if ($assets.get_Count() + $rows.Count -gt 10000) { Stop-DsrInstall 'GitHub release asset inventory exceeds 10000 entries' 7 }
        foreach ($row in $rows) {
            if ($row -isnot [System.Collections.IDictionary] -or
                -not $row.Contains('id') -or ($row.id -isnot [long] -and $row.id -isnot [int]) -or $row.id -le 0 -or
                -not $row.Contains('name') -or $row.name -isnot [string] -or -not $row.name -or
                $row.name.Length -gt 1024 -or $row.name -match '[\x00-\x1f\x7f]' -or
                -not $row.Contains('size') -or ($row.size -isnot [long] -and $row.size -isnot [int]) -or $row.size -lt 0 -or
                -not $row.Contains('state') -or $row.state -isnot [string]) {
                Stop-DsrInstall 'Malformed GitHub release asset identity' 7
            }
            if (-not $ids.Add($row.id) -or $assets.ContainsKey($row.name)) {
                Stop-DsrInstall 'Duplicate GitHub release asset name or identity' 7
            }
            $assets.Add($row.name, @{ id = $row.id; size = $row.size; state = $row.state })
        }
        if ($rows.Count -lt 100) { return ,$assets }
    }
    Stop-DsrInstall 'GitHub release asset inventory exceeds 10000 entries' 7
}

function Save-DsrReleaseAsset {
    param([string]$Repository, [string]$Tag, [string]$Name, [string]$Destination, $Inventory = $null,
          [switch]$Optional, [long]$MaximumBytes = 2147483648)
    if ($null -eq $Inventory) {
        $url = 'https://github.com/' + $Repository + '/releases/download/' + [Uri]::EscapeDataString($Tag) + '/' + [Uri]::EscapeDataString($Name)
        return Invoke-DsrDownload $url $Destination -Optional:$Optional -MaximumBytes $MaximumBytes
    }
    if (-not $Inventory.ContainsKey($Name)) {
        if ($Optional) { return $false }
        Stop-DsrInstall ('Selected release asset is missing: ' + $Name) 8
    }
    $asset = $Inventory[$Name]
    if ($asset.state -cne 'uploaded' -or $asset.size -le 0 -or $asset.size -gt $MaximumBytes) {
        Stop-DsrInstall ('Selected release asset is incomplete or exceeds its size limit: ' + $Name) 7
    }
    $url = 'https://api.github.com/repos/' + $Repository + '/releases/assets/' + $asset.id
    # An existing inventory member cannot be treated as an optional miss when
    # its download fails; do not hide deletion/authentication errors by trying
    # a different checksum format or a public anonymous path.
    $null = Invoke-DsrDownload $url $Destination -ApiAsset -MaximumBytes $MaximumBytes
    if ([IO.FileInfo]::new((Get-DsrPlainPath $Destination -File)).Length -ne $asset.size) {
        Stop-DsrInstall ('Release asset size changed after discovery: ' + $Name) 7
    }
    return $true
}

function Get-DsrChecksumNames {
    param($Binding)
    $number = if ($Binding.tag.StartsWith('v', [StringComparison]::Ordinal)) { $Binding.tag.Substring(1) } else { $Binding.tag }
    $names = @('SHA256SUMS', ($Binding.asset + '.sha256'), 'checksums.sha256', 'SHA256SUMS.txt', 'checksums.txt')
    $versioned = $Binding.tool + '-' + $number + '-SHA256SUMS.txt'
    if (Test-DsrWindowsName $versioned) { $names += $versioned }
    return $names
}

function Get-DsrSelectedChecksum {
    param([string]$Path, [string]$Asset, [string]$ChecksumName)
    $text = Read-DsrTextFile $Path
    $selected = [Collections.Generic.List[string]]::new()
    $names = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($line in ($text -split "`n")) {
        $line = $line.TrimEnd("`r")
        if (-not $line) { continue }
        if ($ChecksumName -ceq ($Asset + '.sha256') -and $line -cmatch '^[0-9a-fA-F]{64}$') {
            $selected.Add($line.ToLowerInvariant())
        } elseif ($line -cmatch '^([0-9a-fA-F]{64}) [ *]([^\r\n]+)$') {
            $hash = $Matches[1].ToLowerInvariant()
            $name = $Matches[2]
            if (-not (Test-DsrName $name) -or -not $names.Add($name)) { Stop-DsrInstall 'Unsafe or duplicate checksum entry' 7 }
            if ($name -ceq $Asset) { $selected.Add($hash) }
        } else { Stop-DsrInstall 'Malformed checksum evidence' 7 }
    }
    if ($selected.Count -ne 1) { Stop-DsrInstall 'Checksum evidence must select the exact payload exactly once' 7 }
    return $selected[0]
}

function Assert-DsrSignature {
    param([string]$Payload, [string]$Signature, [string]$PublicKey)
    if (-not $PublicKey) { return }
    $null = Get-DsrPlainPath $Signature -File
    $command = Get-Command minisign -CommandType Application -ErrorAction SilentlyContinue
    if ($null -eq $command) { Stop-DsrInstall 'The configured signing key requires Minisign; install it before retrying' 3 }
    $start = [Diagnostics.ProcessStartInfo]::new()
    $start.FileName = $command.Source
    $start.UseShellExecute = $false
    $start.RedirectStandardOutput = $true
    $start.RedirectStandardError = $true
    foreach ($argument in @('-Vm', $Payload, '-x', $Signature, '-P', $PublicKey, '-H')) { $start.ArgumentList.Add($argument) }
    $process = [Diagnostics.Process]::new()
    $process.StartInfo = $start
    try {
        if (-not $process.Start()) { Stop-DsrInstall 'Could not start Minisign' 3 }
        $output = $process.StandardOutput.ReadToEndAsync()
        $errorOutput = $process.StandardError.ReadToEndAsync()
        if (-not $process.WaitForExit(60000)) {
            $process.Kill($true)
            $process.WaitForExit()
            Stop-DsrInstall 'Minisign verification timed out' 7
        }
        $null = $output.GetAwaiter().GetResult()
        $null = $errorOutput.GetAwaiter().GetResult()
        if ($process.ExitCode -ne 0) { Stop-DsrInstall 'Minisign signature verification failed' 7 }
    } finally { $process.Dispose() }
}

function Assert-DsrPeMachine {
    param([string]$Path, [string]$Platform)
    $expected = @{ 'windows/amd64' = 0x8664; 'windows/arm64' = 0xaa64; 'windows/386' = 0x014c }[$Platform]
    $stream = Open-DsrReadFile $Path
    $reader = [IO.BinaryReader]::new($stream)
    try {
        if ($stream.Length -lt 96 -or $reader.ReadUInt16() -ne 0x5a4d) { Stop-DsrInstall 'Selected executable is not a PE image' 7 }
        $stream.Position = 0x3c
        $offset = $reader.ReadUInt32()
        if ($offset -lt 64 -or $offset -gt $stream.Length - 26) { Stop-DsrInstall 'Invalid PE header location' 7 }
        $stream.Position = $offset
        if ($reader.ReadUInt32() -ne 0x00004550 -or $reader.ReadUInt16() -ne $expected) {
            Stop-DsrInstall 'Executable machine does not match the selected Windows platform' 7
        }
        $stream.Position = $offset + 20
        $optionalSize = $reader.ReadUInt16()
        $characteristics = $reader.ReadUInt16()
        $magic = $reader.ReadUInt16()
        $expectedMagic = if ($Platform -ceq 'windows/386') { 0x10b } else { 0x20b }
        if ($optionalSize -lt 2 -or $offset + 24 + $optionalSize -gt $stream.Length -or
            ($characteristics -band 2) -eq 0 -or ($characteristics -band 0x2000) -ne 0 -or $magic -ne $expectedMagic) {
            Stop-DsrInstall 'Invalid executable PE image or incompatible optional header' 7
        }
    } finally { $reader.Dispose(); $stream.Dispose() }
}

function Add-DsrArchiveMemberPath {
    param([string]$Name, [bool]$Directory, $Nodes, $ExplicitNames, [string]$Format)
    $path = if ($Directory -and $Name.EndsWith('/', [StringComparison]::Ordinal)) {
        $Name.Substring(0, $Name.Length - 1)
    } else { $Name }
    $parts = $path.Split('/')
    if (-not $path -or $path.Length -gt 1024 -or $parts.Count -gt 16 -or
        -not $ExplicitNames.Add($path)) { Stop-DsrInstall ('Unsafe or duplicate ' + $Format + ' member') 7 }
    foreach ($part in $parts) {
        if (-not (Test-DsrWindowsName $part)) { Stop-DsrInstall ('Unsafe Windows ' + $Format + ' member path') 7 }
    }
    $cursor = ''
    for ($index = 0; $index -lt $parts.Count; $index++) {
        $cursor = if ($cursor) { $cursor + '/' + $parts[$index] } else { $parts[$index] }
        $kind = if ($index -lt $parts.Count - 1 -or $Directory) { 'directory' } else { 'file' }
        if ($Nodes.ContainsKey($cursor)) {
            if ($Nodes[$cursor] -cne ('directory:' + $cursor) -or $kind -cne 'directory') {
                Stop-DsrInstall ('Case-colliding ' + $Format + ' paths or file/directory conflict') 7
            }
        } else { $Nodes.Add($cursor, $kind + ':' + $cursor) }
    }
    return ,$parts
}

function New-DsrTarReadStream {
    param([IO.Stream]$Stream)
    if (-not ('DsrWindowsTarReadStream' -as [type])) {
        # TarReader before .NET 11 does not check header checksums, and it
        # materializes extended-name/PAX metadata before returning an entry.
        # Validate physical framing and budgets as bytes reach that reader.
        # The wrapper retains one header, never an expanded archive or entry.
        Add-Type -TypeDefinition @'
using System;
using System.IO;
public sealed class DsrWindowsTarReadStream : Stream {
    private readonly Stream source;
    private readonly long maximum;
    private readonly byte[] header = new byte[512];
    private static readonly uint[] crcTable = MakeCrcTable();
    private uint crc = 0xffffffff;
    private int headerBytes, entries;
    private long remaining, consumed, zeroBytes;
    private bool ended;
    public DsrWindowsTarReadStream(Stream source, long maximum) { this.source = source; this.maximum = maximum; }
    private static uint[] MakeCrcTable() {
        uint[] table = new uint[256];
        for (uint i = 0; i < table.Length; i++) {
            uint value = i;
            for (int bit = 0; bit < 8; bit++) value = (value & 1) != 0 ? (value >> 1) ^ 0xedb88320 : value >> 1;
            table[i] = value;
        }
        return table;
    }
    public uint Crc32 => ~crc;
    private static long Octal(byte[] bytes, int offset, int length) {
        long value = 0; bool digits = false, tail = false;
        for (int i = offset; i < offset + length; i++) {
            byte b = bytes[i];
            if (b == 0 || b == 32) { if (digits) tail = true; continue; }
            if (tail || b < 48 || b > 55) throw new InvalidDataException("Invalid TAR numeric field");
            digits = true; value = checked(value * 8 + b - 48);
        }
        return value;
    }
    private void Header() {
        bool zero = true; long checksum = 0;
        for (int i = 0; i < 512; i++) { zero &= header[i] == 0; checksum += i >= 148 && i < 156 ? 32 : header[i]; }
        if (zero) { ended = true; zeroBytes = 512; return; }
        if (++entries > 10000 || Octal(header, 148, 8) != checksum)
            throw new InvalidDataException("Invalid TAR entry count or header checksum");
        byte type = header[156];
        if (type != 0 && type != 48 && type != 53 && type != 120 && type != 103 && type != 76)
            throw new InvalidDataException("Linked or unsupported TAR member");
        long size = Octal(header, 124, 12);
        bool metadata = type == 120 || type == 103 || type == 76;
        if (size > (metadata ? 1048576L : 2147483648L) || (type == 53 && size != 0))
            throw new InvalidDataException("TAR member exceeds its admission limit");
        remaining = checked((size + 511) / 512 * 512);
    }
    public override int Read(byte[] buffer, int offset, int count) {
        int read = source.Read(buffer, offset, count);
        consumed = checked(consumed + read);
        if (consumed > maximum) throw new InvalidDataException("TAR expanded stream exceeds its admission limit");
        int limit = offset + read;
        for (int i = offset; i < limit; i++) crc = crcTable[(crc ^ buffer[i]) & 255] ^ (crc >> 8);
        while (offset < limit) {
            if (ended) {
                for (; offset < limit; offset++) {
                    if (buffer[offset] != 0) throw new InvalidDataException("Nonzero content follows the TAR terminator");
                    zeroBytes++;
                }
            } else if (remaining > 0) {
                int take = (int)Math.Min(remaining, limit - offset); remaining -= take; offset += take;
            } else {
                int take = Math.Min(512 - headerBytes, limit - offset);
                Buffer.BlockCopy(buffer, offset, header, headerBytes, take); headerBytes += take; offset += take;
                if (headerBytes == 512) { Header(); headerBytes = 0; }
            }
        }
        return read;
    }
    public void Complete() {
        byte[] buffer = new byte[65536];
        while (Read(buffer, 0, buffer.Length) != 0) { }
        if (!ended || zeroBytes < 1024 || consumed % 512 != 0 || entries == 0)
            throw new InvalidDataException("Truncated or empty TAR archive");
    }
    public override bool CanRead => true;
    public override bool CanSeek => false;
    public override bool CanWrite => false;
    public override long Length => throw new NotSupportedException();
    public override long Position { get => consumed; set => throw new NotSupportedException(); }
    public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
    public override void SetLength(long value) => throw new NotSupportedException();
    public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
    public override void Flush() { }
}
'@
    }
    # The complete decompressed stream budget includes member data, padding
    # and metadata. Do not allocate from any untrusted header's declared size.
    return [DsrWindowsTarReadStream]::new($Stream, $script:DsrMaximumExpandedBytes)
}

function Expand-DsrTarGzipPayload {
    param([string]$Payload, $Selection, [string]$Destination)
    $stream = Open-DsrReadFile $Payload
    $gzip = $null; $bounded = $null; $archive = $null
    try {
        $gzip = [IO.Compression.GZipStream]::new($stream, [IO.Compression.CompressionMode]::Decompress, $true)
        $bounded = New-DsrTarReadStream $gzip
        $archive = [System.Formats.Tar.TarReader]::new($bounded, $true)
        $nodes = [Collections.Generic.Dictionary[string, string]]::new([StringComparer]::OrdinalIgnoreCase)
        $explicitNames = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $selected = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $buffer = [byte[]]::new(1048576)
        $expanded = 0L; $entries = 0
        while ($null -ne ($entry = $archive.GetNextEntry($false))) {
            if (++$entries -gt 10000) { Stop-DsrInstall 'Invalid TAR entry count' 7 }
            # PAX can encode sparse files while keeping a regular-file type.
            # TarReader exposes those attributes without reconstructing the
            # sparse layout; do not install their packed data as an executable.
            $attributes = $null
            if ($entry -is [System.Formats.Tar.PaxTarEntry]) { $attributes = $entry.ExtendedAttributes }
            elseif ($entry -is [System.Formats.Tar.PaxGlobalExtendedAttributesTarEntry]) {
                $attributes = $entry.GlobalExtendedAttributes
            }
            if ($null -ne $attributes) {
                foreach ($key in $attributes.Keys) {
                    if ($key.StartsWith('GNU.sparse.', [StringComparison]::Ordinal) -or
                        $key -ceq 'SCHILY.realsize' -or
                        ($key -ceq 'SCHILY.filetype' -and $attributes[$key] -ceq 'sparse')) {
                        Stop-DsrInstall 'Sparse TAR metadata is unsupported' 7
                    }
                }
            }
            if ($entry.EntryType -eq [System.Formats.Tar.TarEntryType]::GlobalExtendedAttributes) { continue }
            $directory = $entry.EntryType -eq [System.Formats.Tar.TarEntryType]::Directory
            if (-not $directory -and $entry.EntryType -ne [System.Formats.Tar.TarEntryType]::RegularFile -and
                $entry.EntryType -ne [System.Formats.Tar.TarEntryType]::V7RegularFile) {
                Stop-DsrInstall 'Linked or unsupported TAR member' 7
            }
            $parts = Add-DsrArchiveMemberPath $entry.Name $directory $nodes $explicitNames 'TAR'
            $expanded += $entry.Length
            if ($entry.Length -lt 0 -or $entry.Length -gt $script:DsrMaximumPayloadBytes -or
                $expanded -gt $script:DsrMaximumExpandedBytes -or ($directory -and $entry.Length -ne 0)) {
                Stop-DsrInstall 'TAR expanded size exceeds admission limits' 7
            }
            if ($directory) { continue }
            foreach ($binary in $Selection.binaries) {
                if (-not $parts[-1].Equals($binary, [StringComparison]::OrdinalIgnoreCase)) { continue }
                if (-not $selected.Add($binary) -or $entry.Length -eq 0 -or $null -eq $entry.DataStream) {
                    Stop-DsrInstall 'Missing or ambiguous executable TAR member' 7
                }
                $outgoing = New-DsrPrivateFile ([IO.Path]::Combine($Destination, $binary))
                try {
                    $written = 0L
                    while (($count = $entry.DataStream.Read($buffer, 0, $buffer.Length)) -gt 0) {
                        $written += $count
                        if ($written -gt $entry.Length) { Stop-DsrInstall 'TAR member exceeds its declared size' 7 }
                        $outgoing.Write($buffer, 0, $count)
                    }
                    if ($written -ne $entry.Length) { Stop-DsrInstall 'Truncated TAR executable' 7 }
                    $outgoing.Flush($true)
                } finally { $outgoing.Dispose() }
            }
        }
        # TarReader stops at the first zero header. Drain through the same
        # bounded framing reader to reject hidden entries, trailing garbage,
        # incomplete terminators and gzip corruption before installation.
        $bounded.Complete()
        # GZipStream may report clean EOF when an entire gzip footer is
        # missing. Bind the actual final trailer to every decompressed byte
        # instead of treating the TAR terminator as compression completion.
        if ($stream.Length -lt 18) { Stop-DsrInstall 'Truncated gzip payload' 7 }
        $stream.Position = $stream.Length - 8
        $footer = [IO.BinaryReader]::new($stream, [Text.Encoding]::UTF8, $true)
        try {
            if ($footer.ReadUInt32() -ne $bounded.Crc32 -or
                $footer.ReadUInt32() -ne ($bounded.Position -band 4294967295L)) {
                Stop-DsrInstall 'Invalid or missing gzip checksum/length trailer' 7
            }
        } finally { $footer.Dispose() }
        if ($selected.Count -ne $Selection.binaries.Count) { Stop-DsrInstall 'TAR does not contain every selected executable' 7 }
    } finally {
        if ($null -ne $archive) { $archive.Dispose() }
        if ($null -ne $bounded) { $bounded.Dispose() }
        if ($null -ne $gzip) { $gzip.Dispose() }
        $stream.Dispose()
    }
}

function Expand-DsrPayload {
    param([string]$Payload, $Selection, [string]$Platform, [string]$Destination)
    $null = New-DsrPrivateDirectory $Destination
    if ($Selection.format -ceq 'none') {
        Copy-DsrNewFile $Payload ([IO.Path]::Combine($Destination, $Selection.binaries[0]))
    } elseif ($Selection.format -ceq 'tar.gz') {
        Expand-DsrTarGzipPayload $Payload $Selection $Destination
    } else {
        $stream = Open-DsrReadFile $Payload
        $archive = $null
        try {
            $archive = [IO.Compression.ZipArchive]::new($stream, [IO.Compression.ZipArchiveMode]::Read, $true)
            if ($archive.Entries.Count -eq 0 -or $archive.Entries.Count -gt 10000) { Stop-DsrInstall 'Invalid ZIP entry count' 7 }
            $nodes = [Collections.Generic.Dictionary[string, string]]::new([StringComparer]::OrdinalIgnoreCase)
            $explicitNames = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $selected = @{}
            $expanded = 0L
            foreach ($entry in $archive.Entries) {
                $name = $entry.FullName
                $directory = $name.EndsWith('/', [StringComparison]::Ordinal)
                $parts = Add-DsrArchiveMemberPath $name $directory $nodes $explicitNames 'ZIP'
                $type = ([long]$entry.ExternalAttributes -shr 16) -band 0xf000
                if (($type -ne 0 -and $type -ne 0x8000 -and $type -ne 0x4000) -or
                    ($entry.ExternalAttributes -band 0x400) -ne 0 -or
                    ($directory -and $type -eq 0x8000) -or (-not $directory -and $type -eq 0x4000)) {
                    Stop-DsrInstall 'Linked or unsupported ZIP member' 7
                }
                $expanded += $entry.Length
                if ($entry.Length -lt 0 -or $entry.Length -gt $script:DsrMaximumPayloadBytes -or
                    $expanded -gt $script:DsrMaximumExpandedBytes -or ($directory -and $entry.Length -ne 0)) {
                    Stop-DsrInstall 'ZIP expanded size exceeds admission limits' 7
                }
                if (-not $directory) {
                    foreach ($binary in $Selection.binaries) {
                        if ($parts[-1].Equals($binary, [StringComparison]::OrdinalIgnoreCase)) {
                            if ($selected.ContainsKey($binary) -or $entry.Length -eq 0) { Stop-DsrInstall 'Missing or ambiguous executable ZIP member' 7 }
                            $selected[$binary] = $entry
                        }
                    }
                }
            }
            if ($selected.Count -ne $Selection.binaries.Count) { Stop-DsrInstall 'ZIP does not contain every selected executable' 7 }
            foreach ($binary in $Selection.binaries) {
                $entry = $selected[$binary]
                $incoming = $entry.Open()
                try {
                    $outgoing = New-DsrPrivateFile ([IO.Path]::Combine($Destination, $binary))
                    try {
                        $buffer = [byte[]]::new(1048576)
                        $written = 0L
                        while (($count = $incoming.Read($buffer, 0, $buffer.Length)) -gt 0) {
                            $written += $count
                            if ($written -gt $entry.Length) { Stop-DsrInstall 'ZIP member exceeds its declared size' 7 }
                            $outgoing.Write($buffer, 0, $count)
                        }
                        if ($written -ne $entry.Length) { Stop-DsrInstall 'Truncated ZIP executable' 7 }
                        $outgoing.Flush($true)
                    } finally { $outgoing.Dispose() }
                } finally { $incoming.Dispose() }
            }
        } finally {
            if ($null -ne $archive) { $archive.Dispose() }
            $stream.Dispose()
        }
    }
    foreach ($binary in $Selection.binaries) { Assert-DsrPeMachine ([IO.Path]::Combine($Destination, $binary)) $Platform }
}

function Get-DsrCacheReceipt {
    param([string]$Directory, $Binding, [string]$PublicKey)
    $null = Get-DsrPlainPath $Directory -Directory
    Assert-DsrCacheCustody $Directory
    $receipt = ConvertFrom-DsrJson (Read-DsrTextFile ([IO.Path]::Combine($Directory, 'cache.json')) 65536)
    Assert-DsrFields $receipt @('schema_version', 'policy_sha256', 'tool', 'repo', 'tag', 'platform', 'asset', 'format',
        'checksum_file', 'sha256', 'size_bytes', 'signature_sha256')
    foreach ($name in $Binding.Keys) {
        if ($receipt[$name] -cne $Binding[$name]) { Stop-DsrInstall 'Cached release belongs to a different installer selection' 7 }
    }
    if ($receipt.checksum_file -cnotin @(Get-DsrChecksumNames $Binding) -or
        $receipt.sha256 -cnotmatch '^[0-9a-f]{64}$' -or $receipt.size_bytes -isnot [long] -or
        $receipt.size_bytes -le 0 -or $receipt.size_bytes -gt $script:DsrMaximumPayloadBytes) {
        Stop-DsrInstall 'Malformed release cache receipt' 7
    }
    $payload = [IO.Path]::Combine($Directory, $Binding.asset)
    $expected = Get-DsrSelectedChecksum ([IO.Path]::Combine($Directory, $receipt.checksum_file)) $Binding.asset $receipt.checksum_file
    $evidence = Get-DsrFileEvidence $payload
    if ($expected -cne $receipt.sha256 -or $evidence.sha256 -cne $expected -or $evidence.size_bytes -ne $receipt.size_bytes) {
        Stop-DsrInstall 'Cached payload differs from its checksum evidence' 7
    }
    $allowed = @('cache.json', $Binding.asset, $receipt.checksum_file)
    if ($PublicKey) {
        $signature = [IO.Path]::Combine($Directory, ($Binding.asset + '.minisig'))
        if ($receipt.signature_sha256 -cnotmatch '^[0-9a-f]{64}$' -or
            (Get-DsrFileEvidence $signature).sha256 -cne $receipt.signature_sha256) { Stop-DsrInstall 'Cached signature evidence changed' 7 }
        Assert-DsrSignature $payload $signature $PublicKey
        $allowed += ($Binding.asset + '.minisig')
    } elseif ($null -ne $receipt.signature_sha256) { Stop-DsrInstall 'Unexpected cached signing policy' 7 }
    foreach ($entry in [IO.Directory]::EnumerateFileSystemEntries($Directory)) {
        if ([IO.Path]::GetFileName($entry) -cnotin $allowed) { Stop-DsrInstall 'Unexpected file in release cache' 7 }
        $null = Get-DsrPlainPath $entry -File
        Assert-DsrCacheCustody $entry
    }
    return $receipt
}

__DSR_WINDOWS_SOURCE_ENGINE__

function Move-DsrInstalledFile {
    param([string]$Source, [string]$Destination)
    [IO.File]::Move($Source, $Destination, $true)
}

function Publish-DsrInstallJournal {
    param([string]$Source, [string]$Destination)
    [IO.File]::Move($Source, $Destination, $false)
}

function Open-DsrInstallLease {
    param([string]$Prefix)
    $lockPath = Get-DsrPlainPath ([IO.Path]::Combine($Prefix, '.dsr-windows-install.lock'))
    $lease = $null
    $created = $false
    try {
        try {
            $lease = New-DsrPrivateFile $lockPath
            $created = $true
        } catch [IO.IOException] {
            try { $lease = [IO.FileStream]::new($lockPath, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::None) }
            catch [IO.IOException] { Stop-DsrInstall 'Installation directory is busy; retry after its active installer exits' 2 }
        }
        # Keep the same persistent pathname for every kernel-lock generation.
        if ($created) {
            $bytes = [Text.UTF8Encoding]::new($false).GetBytes('dsr-windows-install-lock-v1')
            $lease.Write($bytes, 0, $bytes.Length)
            $lease.Flush($true)
        } else {
            $lease.Position = 0
            $buffer = [byte[]]::new(64)
            $count = $lease.Read($buffer, 0, $buffer.Length)
            if ($lease.Length -ne $count -or [Text.Encoding]::UTF8.GetString($buffer, 0, $count) -cne 'dsr-windows-install-lock-v1') {
                Stop-DsrInstall 'Reserved installation lock contains unrelated data' 2
            }
        }
        return $lease
    } catch {
        if ($null -ne $lease) { $lease.Dispose() }
        throw
    }
}

function Assert-DsrTransactionEvidence {
    param($Evidence)
    Assert-DsrFields $Evidence @('sha256', 'size_bytes')
    if ($Evidence.sha256 -isnot [string] -or $Evidence.sha256 -cnotmatch '^[0-9a-f]{64}$' -or
        ($Evidence.size_bytes -isnot [long] -and $Evidence.size_bytes -isnot [int]) -or
        $Evidence.size_bytes -lt 0 -or $Evidence.size_bytes -gt $script:DsrMaximumPayloadBytes) {
        Stop-DsrInstall 'Invalid interrupted-installation file evidence' 7
    }
}

function Test-DsrSameEvidence {
    param($Left, $Right)
    if ($null -eq $Left -or $null -eq $Right) { return $null -eq $Left -and $null -eq $Right }
    return $Left.sha256 -ceq $Right.sha256 -and $Left.size_bytes -eq $Right.size_bytes
}

function Get-DsrInstallTransaction {
    param([string]$Prefix, $Identity)
    $pending = Get-DsrPlainPath ([IO.Path]::Combine($Prefix, '.dsr-windows-install.pending.json'))
    if ([IO.Directory]::Exists($pending)) { Stop-DsrInstall 'Reserved installation journal is a directory' 7 }
    if (-not [IO.File]::Exists($pending)) { return $null }
    try {
        Assert-DsrCacheCustody $pending
        $text = Read-DsrTextFile $pending 131072
        $bytes = [Text.UTF8Encoding]::new($false, $true).GetBytes($text)
        $evidence = @{ sha256 = (Get-DsrBytesHash $bytes); size_bytes = [long]$bytes.Length }
        if (-not (Test-DsrSameEvidence $evidence (Get-DsrFileEvidence $pending))) {
            Stop-DsrInstall 'Interrupted-installation journal changed while it was read' 7
        }
        $journal = ConvertFrom-DsrJson $text
        Assert-DsrFields $journal @('schema_version', 'transaction_id', 'tool', 'repository', 'platform', 'prefix', 'binaries')
        if (($journal.schema_version -isnot [long] -and $journal.schema_version -isnot [int]) -or
            $journal.schema_version -ne 1 -or $journal.transaction_id -isnot [string] -or
            $journal.transaction_id -cnotmatch '^[0-9a-f]{32}$' -or
            $journal.tool -isnot [string] -or $journal.tool -cne $Identity.tool -or
            $journal.repository -isnot [string] -or $journal.repository -cne $Identity.repository -or
            $journal.platform -isnot [string] -or $journal.platform -cne $Identity.platform -or
            $journal.prefix -isnot [string] -or -not $journal.prefix.Equals($Prefix, [StringComparison]::OrdinalIgnoreCase) -or
            $journal.binaries -isnot [array] -or $journal.binaries.Count -lt 1 -or $journal.binaries.Count -gt 64) {
            Stop-DsrInstall 'Interrupted-installation journal does not belong to this tool, repository, platform and prefix' 7
        }
        $names = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $rows = @{}
        foreach ($row in $journal.binaries) {
            Assert-DsrFields $row @('name', 'previous', 'installed')
            if (-not (Test-DsrWindowsName $row.name) -or $row.name.Length -gt 200 -or
                -not $row.name.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase) -or -not $names.Add($row.name)) {
                Stop-DsrInstall 'Invalid or colliding interrupted-installation executable names' 7
            }
            Assert-DsrTransactionEvidence $row.installed
            if ($null -ne $row.previous) { Assert-DsrTransactionEvidence $row.previous }
            $rows[$row.name] = $row
        }
        # Only a validated GUID can select a sibling stage. Journal-supplied
        # paths are never combined with the prefix or opened.
        $stage = Get-DsrPlainPath ([IO.Path]::Combine($Prefix, ('.dsr-install-' + $journal.transaction_id))) -Directory
        Assert-DsrCacheCustody $stage
        foreach ($entry in [IO.DirectoryInfo]::new($stage).EnumerateFileSystemInfos()) {
            $null = Get-DsrPlainPath $entry.FullName
            Assert-DsrCacheCustody $entry.FullName
            if ($entry.Name -cin @('new', 'old', 'restore')) {
                if (($entry.Attributes -band [IO.FileAttributes]::Directory) -eq 0) { Stop-DsrInstall 'Transaction staging directory was replaced' 7 }
            } elseif ($entry.Name -cin @('complete.ready', 'complete.json')) {
                if (($entry.Attributes -band [IO.FileAttributes]::Directory) -ne 0) { Stop-DsrInstall 'Transaction completion marker is not a file' 7 }
            } else { Stop-DsrInstall 'Unexpected file in interrupted-installation staging' 7 }
        }
        foreach ($directory in @('new', 'old', 'restore')) {
            $directoryPath = Get-DsrPlainPath ([IO.Path]::Combine($stage, $directory)) -Directory
            Assert-DsrCacheCustody $directoryPath
            $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            foreach ($entry in [IO.DirectoryInfo]::new($directoryPath).EnumerateFileSystemInfos()) {
                $null = Get-DsrPlainPath $entry.FullName -File
                Assert-DsrCacheCustody $entry.FullName
                if (-not $names.Contains($entry.Name) -or -not $seen.Add($entry.Name)) {
                    Stop-DsrInstall 'Unexpected or colliding file in interrupted-installation staging' 7
                }
                $expected = if ($directory -ceq 'new') { $rows[$entry.Name].installed } else { $rows[$entry.Name].previous }
                if ($null -eq $expected) { Stop-DsrInstall 'Unexpected backup for a previously absent executable' 7 }
                # A killed recovery can leave a partial private restore copy;
                # it is never trusted as a backup or installed directly.
                if ($directory -cne 'restore' -and -not (Test-DsrSameEvidence $expected (Get-DsrFileEvidence $entry.FullName))) {
                    Stop-DsrInstall 'Interrupted-installation staged bytes changed' 7
                }
            }
            if ($directory -ceq 'old') {
                foreach ($row in $journal.binaries) {
                    if ($null -ne $row.previous -and -not $seen.Contains($row.name)) {
                        Stop-DsrInstall 'Interrupted-installation backup is missing' 7
                    }
                }
            }
        }
        $state = 'pending'
        $complete = Get-DsrPlainPath ([IO.Path]::Combine($stage, 'complete.json'))
        if ([IO.File]::Exists($complete)) {
            $marker = ConvertFrom-DsrJson (Read-DsrTextFile $complete 4096)
            Assert-DsrFields $marker @('schema_version', 'journal_sha256', 'state')
            if (($marker.schema_version -isnot [long] -and $marker.schema_version -isnot [int]) -or
                $marker.schema_version -ne 1 -or $marker.journal_sha256 -isnot [string] -or
                $marker.journal_sha256 -cne $evidence.sha256 -or $marker.state -cnotin @('committed', 'rolled_back')) {
                Stop-DsrInstall 'Invalid interrupted-installation completion marker' 7
            }
            $state = $marker.state
        }
        return @{ journal = $journal; evidence = $evidence; pending = $pending; stage = $stage; prefix = $Prefix; state = $state }
    } catch {
        if ($_.Exception.Data.Contains('DsrExitCode') -and $_.Exception.Data['DsrExitCode'] -eq 4) {
            $_.Exception.Data['DsrExitCode'] = 7
        }
        throw
    }
}

function Get-DsrTransactionDestination {
    param($Transaction, $Row)
    $path = Get-DsrPlainPath ([IO.Path]::Combine($Transaction.prefix, $Row.name))
    if ([IO.Directory]::Exists($path)) { Stop-DsrInstall 'Recovery destination is a directory' 7 }
    $observed = if ([IO.File]::Exists($path)) { Get-DsrFileEvidence $path } else { $null }
    if ($null -ne $observed -and -not (Test-DsrSameEvidence $observed $Row.previous) -and
        -not (Test-DsrSameEvidence $observed $Row.installed)) {
        Stop-DsrInstall ('Recovery refused because an executable changed outside the interrupted installation: ' + $Row.name) 7
    }
    return $observed
}

function Write-DsrTransactionCompletion {
    param($Transaction, [string]$State)
    if ($State -cnotin @('committed', 'rolled_back')) { Stop-DsrInstall 'Invalid transaction completion state' 7 }
    $ready = Get-DsrPlainPath ([IO.Path]::Combine($Transaction.stage, 'complete.ready'))
    if ([IO.File]::Exists($ready)) { [IO.File]::Delete($ready) }
    $marker = @{ schema_version = 1; journal_sha256 = $Transaction.evidence.sha256; state = $State }
    Write-DsrNewTextFile $ready ($marker | ConvertTo-Json -Compress)
    # Publication is the completion point. Before it, recovery restores the
    # previous family; after it, recovery only finishes private-state cleanup.
    [IO.File]::Move($ready, [IO.Path]::Combine($Transaction.stage, 'complete.json'), $false)
    $Transaction.state = $State
}

function Clear-DsrInstallTransaction {
    param($Transaction)
    $null = Get-DsrPlainPath $Transaction.pending -File
    if (-not (Test-DsrSameEvidence $Transaction.evidence (Get-DsrFileEvidence $Transaction.pending))) {
        Stop-DsrInstall 'Interrupted-installation journal changed before cleanup' 7
    }
    # Never remove backups while a published journal still refers to them.
    [IO.File]::Delete($Transaction.pending)
    try { Remove-DsrPrivateTree $Transaction.stage }
    catch { Write-DsrInstallLog ('Completed private transaction staging retained for inspection: ' + $Transaction.stage) }
}

function Restore-DsrExecutableFamily {
    param($Transaction)
    if ($Transaction.state -cne 'pending') { Stop-DsrInstall 'A completed transaction cannot be rolled back' 7 }
    # Admit the whole current family before the first recovery mutation.
    foreach ($row in $Transaction.journal.binaries) { $null = Get-DsrTransactionDestination $Transaction $row }
    for ($index = $Transaction.journal.binaries.Count - 1; $index -ge 0; $index--) {
        $row = $Transaction.journal.binaries[$index]
        $observed = Get-DsrTransactionDestination $Transaction $row
        if (Test-DsrSameEvidence $observed $row.previous) { continue }
        $path = [IO.Path]::Combine($Transaction.prefix, $row.name)
        if ($null -ne $row.previous) {
            $backup = [IO.Path]::Combine($Transaction.stage, 'old', $row.name)
            if (-not (Test-DsrSameEvidence $row.previous (Get-DsrFileEvidence $backup))) {
                Stop-DsrInstall 'Recovery backup changed before restoration' 7
            }
            $copy = Get-DsrPlainPath ([IO.Path]::Combine($Transaction.stage, 'restore', $row.name))
            if ([IO.File]::Exists($copy)) { [IO.File]::Delete($copy) }
            Copy-DsrNewFile $backup $copy
            if (-not (Test-DsrSameEvidence $row.previous (Get-DsrFileEvidence $copy))) {
                Stop-DsrInstall 'Private restoration copy differs from its backup' 7
            }
            $null = Get-DsrTransactionDestination $Transaction $row
            Move-DsrInstalledFile $copy $path
        } else {
            $null = Get-DsrTransactionDestination $Transaction $row
            if ([IO.File]::Exists($path)) { [IO.File]::Delete($path) }
        }
    }
    $results = @()
    foreach ($row in $Transaction.journal.binaries) {
        $observed = Get-DsrTransactionDestination $Transaction $row
        if (-not (Test-DsrSameEvidence $observed $row.previous)) { Stop-DsrInstall 'Recovery did not restore the previous executable family' 7 }
        $results += @{ name = $row.name; path = [IO.Path]::Combine($Transaction.prefix, $row.name);
            present = ($null -ne $observed); evidence = $observed }
    }
    Write-DsrTransactionCompletion $Transaction 'rolled_back'
    return ,$results
}

function Recover-DsrExecutableFamily {
    param([string]$Prefix, $Identity)
    $prefixPath = Get-DsrPlainPath $Prefix -Directory
    $lease = Open-DsrInstallLease $prefixPath
    try {
        $transaction = Get-DsrInstallTransaction $prefixPath $Identity
        if ($null -eq $transaction) { Stop-DsrInstall 'No interrupted installation is recorded for this prefix' 2 }
        $restored = @()
        $action = 'completed_cleanup'
        if ($transaction.state -ceq 'pending') {
            $restored = Restore-DsrExecutableFamily $transaction
            $action = 'rolled_back'
        }
        $state = $transaction.state
        Clear-DsrInstallTransaction $transaction
        return @{ state = $state; action = $action; binaries = @($restored) }
    } finally { $lease.Dispose() }
}

function Install-DsrExecutableFamily {
    param([string]$Source, [string]$Prefix, [string[]]$Names, $Identity, $ExpectedEvidence = $null, [switch]$Yes)
    $prefixPath = New-DsrDirectoryChain $Prefix
    $lease = Open-DsrInstallLease $prefixPath
    $stage = ''
    $transaction = $null
    $published = $false
    $committed = $false
    $settled = $false
    $retain = $false
    $previous = @{}
    $new = @{}
    try {
        $existing = Get-DsrInstallTransaction $prefixPath $Identity
        if ($null -ne $existing) {
            if ($existing.state -ceq 'pending') {
                Stop-DsrInstall 'An interrupted installation must be restored with -Recover -Yes before installing again' 2
            }
            Clear-DsrInstallTransaction $existing
        }
        foreach ($name in $Names) {
            $path = Get-DsrPlainPath ([IO.Path]::Combine($prefixPath, $name))
            if ([IO.Directory]::Exists($path)) { Stop-DsrInstall 'An executable destination is a directory' 2 }
            if ([IO.File]::Exists($path)) {
                if (-not $Yes) {
                    if ($env:CI -eq '1' -or [Console]::IsInputRedirected) { Stop-DsrInstall 'Existing executables require -Yes for replacement' 2 }
                    $answer = Read-Host ('Replace ' + $path + '? [y/N]')
                    if ($answer -cnotin @('y', 'Y')) { Stop-DsrInstall 'Replacement was not authorized' 2 }
                }
                $previous[$name] = Get-DsrFileEvidence $path
                Assert-DsrTransactionEvidence $previous[$name]
            } else { $previous[$name] = $null }
        }
        $transactionId = [Guid]::NewGuid().ToString('N')
        $stage = New-DsrPrivateDirectory ([IO.Path]::Combine($prefixPath, ('.dsr-install-' + $transactionId)))
        $fresh = New-DsrPrivateDirectory ([IO.Path]::Combine($stage, 'new'))
        $backups = New-DsrPrivateDirectory ([IO.Path]::Combine($stage, 'old'))
        $null = New-DsrPrivateDirectory ([IO.Path]::Combine($stage, 'restore'))
        $rows = @()
        foreach ($name in $Names) {
            Copy-DsrNewFile ([IO.Path]::Combine($Source, $name)) ([IO.Path]::Combine($fresh, $name))
            $new[$name] = Get-DsrFileEvidence ([IO.Path]::Combine($fresh, $name))
            if ($null -ne $ExpectedEvidence) {
                if ($ExpectedEvidence -isnot [Collections.IDictionary] -or $ExpectedEvidence.Count -ne $Names.Count -or
                    -not $ExpectedEvidence.Contains($name)) { Stop-DsrInstall 'Incomplete source executable evidence' 7 }
                Assert-DsrTransactionEvidence $ExpectedEvidence[$name]
                if (-not (Test-DsrSameEvidence $new[$name] $ExpectedEvidence[$name])) {
                    Stop-DsrInstall 'Source executable changed before private installation staging completed' 7
                }
            }
            if ($null -ne $previous[$name]) {
                Copy-DsrNewFile ([IO.Path]::Combine($prefixPath, $name)) ([IO.Path]::Combine($backups, $name))
                $backup = Get-DsrFileEvidence ([IO.Path]::Combine($backups, $name))
                if (-not (Test-DsrSameEvidence $backup $previous[$name])) {
                    Stop-DsrInstall 'Existing executable changed before backup completed' 7
                }
            }
            $rows += @{ name = $name; previous = $previous[$name]; installed = $new[$name] }
        }
        $journal = [ordered]@{ schema_version = 1; transaction_id = $transactionId; tool = $Identity.tool;
            repository = $Identity.repository; platform = $Identity.platform; prefix = $prefixPath; binaries = @($rows) }
        $ready = [IO.Path]::Combine($stage, 'transaction.ready')
        Write-DsrNewTextFile $ready ($journal | ConvertTo-Json -Depth 8 -Compress)
        # No destination may change before this immutable journal is visible.
        # Retain backups even if a handled interruption lands immediately after
        # publication but before the caller can observe its successful return.
        $published = $true
        Publish-DsrInstallJournal $ready ([IO.Path]::Combine($prefixPath, '.dsr-windows-install.pending.json'))
        $transaction = Get-DsrInstallTransaction $prefixPath $Identity
        foreach ($name in $Names) {
            $path = Get-DsrPlainPath ([IO.Path]::Combine($prefixPath, $name))
            if ($null -eq $previous[$name]) {
                if ([IO.File]::Exists($path) -or [IO.Directory]::Exists($path)) { Stop-DsrInstall 'An executable appeared during installation' 2 }
            } else {
                $observed = Get-DsrFileEvidence $path
                if (-not (Test-DsrSameEvidence $observed $previous[$name])) {
                    Stop-DsrInstall 'An installed executable changed during installation' 7
                }
            }
            Move-DsrInstalledFile ([IO.Path]::Combine($fresh, $name)) $path
        }
        $results = @()
        foreach ($name in $Names) {
            $path = Get-DsrPlainPath ([IO.Path]::Combine($prefixPath, $name)) -File
            $observed = Get-DsrFileEvidence $path
            if (-not (Test-DsrSameEvidence $observed $new[$name])) {
                Stop-DsrInstall 'Final installed executable differs from its staged bytes' 7
            }
            $results += @{ name = $name; path = $path; sha256 = $observed.sha256; size_bytes = $observed.size_bytes }
        }
        Write-DsrTransactionCompletion $transaction 'committed'
        $committed = $true
        $settled = $true
        return ,$results
    } finally {
        if ($null -ne $transaction -and -not $committed) {
            try {
                # Re-read the completion point even on a handled interruption:
                # a committed marker can never authorize restoring old bytes.
                $transaction = Get-DsrInstallTransaction $prefixPath $Identity
                if ($null -eq $transaction) { Stop-DsrInstall 'Installation journal disappeared before rollback' 7 }
                if ($transaction.state -ceq 'pending') { $null = Restore-DsrExecutableFamily $transaction }
                $settled = $true
            } catch {
                $retain = $true
                Write-DsrInstallLog ('Rollback could not complete; use -Recover -Yes after resolving the reported state: ' + $_.Exception.Message)
            }
        } elseif ($published -and $null -eq $transaction) { $retain = $true }
        try {
            if ($settled) {
                try { Clear-DsrInstallTransaction $transaction }
                catch { Write-DsrInstallLog ('Completed transaction metadata retained for a later cleanup: ' + $_.Exception.Message) }
            } elseif ($stage -and -not $published -and -not $retain) {
                try { Remove-DsrPrivateTree $stage }
                catch { Write-DsrInstallLog ('Private transaction staging retained for inspection: ' + $stage) }
            }
        } finally { $lease.Dispose() }
        if ($retain) { Stop-DsrInstall ('Installation failed; recovery files retained at ' + $stage) 7 }
    }
}

function Install-DsrSourceFamily {
    param($Policy, $Selection, [string]$Platform, [string]$Reference, [string]$Work, [int]$Timeout,
          [string]$CacheRoot, [string]$PrefixPath, $TransactionIdentity, [switch]$Yes)
    Write-DsrInstallLog ('Building ' + $Policy.repo + ' at ' + $Reference + '; this is a local source build, not a signed release')
    $built = Build-DsrSourceFamily $Policy $Selection $Platform $Reference $Work $Timeout
    # Persist byte evidence before activation. This is a build receipt, not an
    # assertion that installation completed; failed activation retains it.
    $history = New-DsrDirectoryChain ([IO.Path]::Combine($CacheRoot, 'source-receipts', $Policy.tool))
    Assert-DsrCacheCustody $history
    $receiptPath = [IO.Path]::Combine($history, ($built.receipt.source_commit + '-' + [Guid]::NewGuid().ToString('N') + '.json'))
    Copy-DsrNewFile ([IO.Path]::Combine($Work, 'source-receipt.json')) $receiptPath
    $receiptEvidence = Get-DsrFileEvidence $receiptPath
    $installed = Install-DsrExecutableFamily $built.directory $PrefixPath $Selection.binaries $TransactionIdentity -ExpectedEvidence $built.expected -Yes:$Yes
    $primary = $Policy.binary_name
    if (-not $primary.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase)) { $primary += '.exe' }
    $primaryRow = @($installed | Where-Object { $_.name.Equals($primary, [StringComparison]::OrdinalIgnoreCase) })[0]
    $result = @{ tool = $Policy.tool; repository = $Policy.repo; status = 'success'; method = 'source'; signed_release = $false;
        source = $built.receipt; platform = $Platform;
        source_receipt = @{ path = $receiptPath; sha256 = $receiptEvidence.sha256; size_bytes = $receiptEvidence.size_bytes };
        path = $primaryRow.path; binaries = @($installed); signature_verified = $false; exit_code = 0 }
    if ($built.receipt.language -ceq 'go') { $result.go_target = $built.receipt.go_target }
    elseif ($built.receipt.language -ceq 'rust') { $result.cargo_target = $built.receipt.cargo_target }
    else { $result.bun_target = $built.receipt.bun_target }
    Write-DsrInstallLog ('Installed ' + $Policy.tool + ' from source commit ' + $built.receipt.source_commit + ' (' + $installed.Count + ' executable(s))')
    return $result
}

function Invoke-DsrWindowsInstaller {
    [CmdletBinding()]
    param([string]$Version = '', [string]$Prefix = '', [string]$CacheDir = '',
          [switch]$Offline, [switch]$Recover, [switch]$FromSource, [switch]$AllowSourceBuild,
          [string]$SourceIfStale = '', [string]$SourceRef = '', [int]$SourceTimeout = 3600,
          [switch]$Yes, [switch]$Json, [switch]$Help)
    $work = ''
    $retainSourceWork = $false
    $freshness = $null
    $freshnessRequested = $PSBoundParameters.ContainsKey('SourceIfStale')
    $fallbackReference = ''
    $fallbackStage = ''
    $fallbackVersion = $null
    $tool = ''
    try {
        if ($PSVersionTable.PSVersion -lt [Version]'7.4') { Stop-DsrInstall 'PowerShell 7.4 or newer is required' 3 }
        $policyEnvelope = Get-DsrInstallPolicy
        $policy = $policyEnvelope.value
        $tool = $policy.tool
        if ($Help) {
            $text = @"
Install $tool on native Windows using verified release payloads.

Options:
  -Version TAG   Exact tag (numeric 1.2.3 also accepts v1.2.3); default: latest
  -Prefix DIR    Destination directory; default: LocalAppData/Programs/$tool/bin
  -CacheDir DIR  Persistent verified download cache
  -Offline       No network; requires -Version and complete cached evidence
  -Recover       Restore an interrupted installation offline; requires -Yes
  -FromSource    Explicitly build a configured Rust/Go/Bun family with installed tools
  -AllowSourceBuild  Permit source fallback when release acquisition is unavailable
  -SourceIfStale N   After verifying latest release, build its observed head if >N commits behind
  -SourceRef REF Source pin: HEAD, refs/heads/BRANCH, refs/tags/TAG, or full SHA
  -SourceTimeout SECONDS  Per-source-command deadline; default 3600, maximum 86400
  -Yes           Authorize replacement of existing selected executables
  -Json          Emit one machine-readable result
  -Verbose       Print additional diagnostics to stderr
  -Help          Show this help

Every selected executable is checked before replacement. Configured release
signatures require Minisign. Release executables are never run and PATH is not edited.
-FromSource and -AllowSourceBuild run repository/dependency build code and produce a local build,
not an authenticated signed release. It never installs a compiler automatically.
-SourceIfStale requires -AllowSourceBuild and latest online mode. Unknown freshness
keeps the verified release. A failed release integrity check never starts a source build.
Source fallback keeps a selected release's exact tag; only unavailable latest
discovery selects HEAD. Credentials remain the same, and authentication failures,
missing verification proof or invalid release metadata never authorize fallback.
Private releases use DSR_GH_TOKEN, GITHUB_TOKEN, then GH_TOKEN, with Contents read
permission. Release credentials are scoped to the configured repository's API;
explicit source fetches use the same token at that repository's HTTPS Git URL.
"@
            if ($Json) { [Console]::Out.WriteLine((@{ tool = $tool; status = 'help'; help = $text } | ConvertTo-Json -Compress)) }
            else { [Console]::Out.WriteLine($text) }
            return 0
        }
        $platform = Get-DsrHostPlatform
        if (-not $policy.platforms.Contains($platform)) { Stop-DsrInstall ('No configured release for ' + $platform) 3 }
        $selection = $policy.platforms[$platform]
        $transactionIdentity = @{ tool = $tool; repository = $policy.repo; platform = $platform }
        $localAppData = [Environment]::GetFolderPath([Environment+SpecialFolder]::LocalApplicationData)
        if (-not $Prefix) { $Prefix = [IO.Path]::Combine($localAppData, 'Programs', $tool, 'bin') }
        $prefixPath = Get-DsrPlainPath $Prefix
        if ($Recover) {
            if ($Version -or $Offline -or $CacheDir -or $FromSource -or $AllowSourceBuild -or
                $freshnessRequested -or $SourceRef -or $SourceTimeout -ne 3600) {
                Stop-DsrInstall '-Recover cannot be combined with release, cache or source-build options'
            }
            if (-not $Yes) { Stop-DsrInstall '-Recover requires -Yes to restore the previous executable family' 2 }
            $recovered = Recover-DsrExecutableFamily $prefixPath $transactionIdentity
            $result = @{ tool = $tool; repository = $policy.repo; status = 'success'; operation = 'recover';
                platform = $platform; path = $prefixPath; recovery_action = $recovered.action;
                transaction_state = $recovered.state; binaries = @($recovered.binaries); exit_code = 0 }
            Write-DsrInstallLog ('Installation recovery for ' + $tool + ': ' + $recovered.action)
            if ($Json) { [Console]::Out.WriteLine(($result | ConvertTo-Json -Depth 12 -Compress)) }
            else { [Console]::Out.WriteLine($prefixPath) }
            return 0
        }
        if (-not $FromSource -and $SourceRef) { Stop-DsrInstall '-SourceRef requires explicit -FromSource consent' }
        if (-not $FromSource -and -not $AllowSourceBuild -and $SourceTimeout -ne 3600) {
            Stop-DsrInstall '-SourceTimeout requires explicit source-build consent'
        }
        if ($freshnessRequested) {
            if (-not $AllowSourceBuild -or $SourceIfStale -cnotmatch '^(0|[1-9][0-9]{0,5})$' -or
                $FromSource -or $Version -or $Offline) {
                Stop-DsrInstall '-SourceIfStale needs -AllowSourceBuild, an integer from 0 through 999999, and latest online release mode'
            }
        }
        if ($FromSource -or $AllowSourceBuild) {
            if ($Offline) { Stop-DsrInstall 'Source-build consent cannot be combined with -Offline' }
            if (-not $policy.Contains('source')) { Stop-DsrInstall 'This installer has no supported Rust, Go or Bun source policy' 4 }
            if ($SourceTimeout -lt 1 -or $SourceTimeout -gt 86400) { Stop-DsrInstall '-SourceTimeout must be between 1 and 86400 seconds' }
        }
        if ($FromSource) {
            if ($Version -or $Offline) { Stop-DsrInstall '-FromSource cannot be combined with -Version or -Offline; select -SourceRef instead' }
            if (-not $SourceRef) { $SourceRef = 'HEAD' }
        }
        if ($Offline -and -not $Version) { Stop-DsrInstall '-Offline requires an explicit -Version' }
        if ($Version -and -not (Test-DsrName $Version)) { Stop-DsrInstall 'Invalid release version' }
        if (-not $CacheDir) { $CacheDir = [IO.Path]::Combine($localAppData, 'dsr', 'cache', 'installers') }
        $cacheRoot = Get-DsrPlainPath $CacheDir
        if (Test-DsrPathsOverlap $prefixPath $cacheRoot) { Stop-DsrInstall 'Installation and download cache paths must not overlap' }
        if (-not $Offline) { $null = New-DsrDirectoryChain $cacheRoot }
        else { $null = Get-DsrPlainPath $cacheRoot -Directory }
        Assert-DsrCacheCustody $cacheRoot
        if ($FromSource) {
            $work = New-DsrPrivateDirectory ([IO.Path]::Combine($cacheRoot, ('.dsr-source-' + [Guid]::NewGuid().ToString('N'))))
            $retainSourceWork = $true
            $result = Install-DsrSourceFamily $policy $selection $platform $SourceRef $work $SourceTimeout $cacheRoot $prefixPath $transactionIdentity -Yes:$Yes
            $retainSourceWork = $false
            if ($Json) { [Console]::Out.WriteLine(($result | ConvertTo-Json -Depth 12 -Compress)) }
            else { [Console]::Out.WriteLine($result.path) }
            return 0
        }
        $release = $null
        if (-not $Version) {
            $work = New-DsrPrivateDirectory ([IO.Path]::Combine($cacheRoot, ('.dsr-download-' + [Guid]::NewGuid().ToString('N'))))
            $latest = [IO.Path]::Combine($work, 'latest.json')
            $authenticatedDiscovery = [bool](Get-DsrGitHubToken)
            $latestDownloaded = $false
            try {
                $null = Invoke-DsrDownload ('https://api.github.com/repos/' + $policy.repo + '/releases/latest') $latest -MaximumBytes 8388608
                $latestDownloaded = $true
            } catch {
                # A selected credential never falls back to an anonymous
                # identity. Malformed metadata and unsafe API redirects are
                # not availability failures and must also remain refusals.
                if ($authenticatedDiscovery) {
                    if ($AllowSourceBuild -and (Test-DsrReleaseAcquisitionUnavailable $_.Exception)) {
                        $fallbackReference = 'HEAD'
                        $fallbackStage = 'release_discovery'
                    }
                    throw
                }
                if (-not $_.Exception.Data.Contains('DsrTransientAcquisition') -or
                    $_.Exception.Data['DsrTransientAcquisition'] -ne $true) {
                    if ($AllowSourceBuild -and (Test-DsrReleaseAcquisitionUnavailable $_.Exception -AllowMissing)) {
                        $fallbackReference = 'HEAD'
                        $fallbackStage = 'release_discovery'
                    }
                    throw
                }
                Write-DsrInstallLog 'GitHub API unavailable; resolving the public latest-release redirect'
                $allowDiscoveryFallback = $AllowSourceBuild -and
                    (Test-DsrReleaseAcquisitionUnavailable $_.Exception -AllowMissing)
                try { $tag = Get-DsrPublicLatestTag $policy.repo }
                catch {
                    if ($allowDiscoveryFallback -and (Test-DsrReleaseAcquisitionUnavailable $_.Exception -AllowMissing)) {
                        $fallbackReference = 'HEAD'
                        $fallbackStage = 'release_discovery'
                    }
                    throw
                }
            }
            if ($latestDownloaded) {
                $release = ConvertFrom-DsrJson (Read-DsrTextFile $latest)
                if ($release -isnot [System.Collections.IDictionary] -or -not $release.Contains('tag_name') -or
                    -not (Test-DsrName $release.tag_name)) { Stop-DsrInstall 'Invalid latest-release identity' 7 }
                Assert-DsrReleaseIdentity $release $release.tag_name
                if (-not $release.Contains('prerelease') -or $release.prerelease -isnot [bool] -or $release.prerelease) {
                    Stop-DsrInstall 'Latest release is not a published full release' 7
                }
                $tag = $release.tag_name
            }
        } else { $tag = if ($Version -cmatch '^[0-9]') { 'v' + $Version } else { $Version } }
        $number = if ($tag.StartsWith('v', [StringComparison]::Ordinal)) { $tag.Substring(1) } else { $tag }
        $asset = $selection.name.Replace('${version}', $number)
        if (-not (Test-DsrWindowsName $asset)) { Stop-DsrInstall 'Resolved payload name is unsafe' }
        Write-DsrInstallVerbose ('Selected ' + $platform + ' release ' + $tag + ': ' + $asset)
        $binding = [ordered]@{ schema_version = 1; policy_sha256 = $policyEnvelope.sha256; tool = $tool; repo = $policy.repo;
            tag = $tag; platform = $platform; asset = $asset; format = $selection.format }
        if ($asset -iin @('cache.json') + @(Get-DsrChecksumNames $binding)) {
            Stop-DsrInstall 'Selected payload name collides with release verification metadata'
        }
        $identity = Get-DsrBytesHash ([Text.Encoding]::UTF8.GetBytes(($binding | ConvertTo-Json -Compress)))
        $cache = [IO.Path]::Combine($cacheRoot, ($tool + '-' + $identity))
        $null = Get-DsrPlainPath $cache
        if ([IO.Directory]::Exists($cache)) {
            Write-DsrInstallVerbose 'Revalidating the exact cached release and its proof'
            $receipt = Get-DsrCacheReceipt $cache $binding $policy.public_key
        } elseif ($Offline) { Stop-DsrInstall 'No complete verified cache exists for this exact release selection' 7 }
        else {
            if (-not $work) { $work = New-DsrPrivateDirectory ([IO.Path]::Combine($cacheRoot, ('.dsr-download-' + [Guid]::NewGuid().ToString('N')))) }
            $inventory = $null
            $authenticatedAcquisition = [bool](Get-DsrGitHubToken)
            if ($authenticatedAcquisition) {
                Write-DsrInstallVerbose 'Resolving the selected authenticated GitHub release and complete asset inventory'
                try {
                    if ($null -eq $release) {
                        $metadata = [IO.Path]::Combine($work, 'release.json')
                        $releaseUrl = 'https://api.github.com/repos/' + $policy.repo + '/releases/tags/' + [Uri]::EscapeDataString($tag)
                        $null = Invoke-DsrDownload $releaseUrl $metadata -MaximumBytes 8388608
                        $release = ConvertFrom-DsrJson (Read-DsrTextFile $metadata)
                    }
                    Assert-DsrReleaseIdentity $release $tag
                    $inventory = Get-DsrReleaseAssets $policy.repo $release.id $work
                } catch {
                    if ($AllowSourceBuild -and (Test-DsrReleaseAcquisitionUnavailable $_.Exception)) {
                        $fallbackReference = 'refs/tags/' + $tag
                        $fallbackVersion = $tag
                        $fallbackStage = 'release_metadata'
                    }
                    throw
                }
            } else { Write-DsrInstallVerbose 'Downloading the selected public GitHub release payload' }
            $download = New-DsrPrivateDirectory ([IO.Path]::Combine($work, 'release'))
            $payload = [IO.Path]::Combine($download, $asset)
            try {
                $null = Save-DsrReleaseAsset $policy.repo $tag $asset $payload $inventory -MaximumBytes $script:DsrMaximumPayloadBytes
            } catch {
                # A complete, authenticated inventory can prove absence of
                # this primary payload. An HTTP 404 cannot prove that same
                # fact: a private repository may hide denied access as 404.
                $missingInventoryPayload = $null -ne $inventory -and -not $inventory.ContainsKey($asset) -and
                    $_.Exception.Data.Contains('DsrExitCode') -and $_.Exception.Data['DsrExitCode'] -eq 8
                if ($AllowSourceBuild -and ($missingInventoryPayload -or
                    (Test-DsrReleaseAcquisitionUnavailable $_.Exception -AllowMissing:(-not $authenticatedAcquisition)))) {
                    $fallbackReference = 'refs/tags/' + $tag
                    $fallbackVersion = $tag
                    $fallbackStage = 'release_payload'
                }
                throw
            }
            $checksumName = ''
            foreach ($candidate in @(Get-DsrChecksumNames $binding)) {
                if (Save-DsrReleaseAsset $policy.repo $tag $candidate ([IO.Path]::Combine($download, $candidate)) $inventory -Optional -MaximumBytes 8388608) {
                    $checksumName = $candidate
                    break
                }
            }
            if (-not $checksumName) { Stop-DsrInstall 'No checksum evidence was published for this payload' 7 }
            $expected = Get-DsrSelectedChecksum ([IO.Path]::Combine($download, $checksumName)) $asset $checksumName
            $evidence = Get-DsrFileEvidence $payload
            if ($evidence.size_bytes -eq 0 -or $evidence.sha256 -cne $expected) { Stop-DsrInstall 'Downloaded payload checksum mismatch' 7 }
            $signatureHash = $null
            if ($policy.public_key) {
                $signature = [IO.Path]::Combine($download, ($asset + '.minisig'))
                $null = Save-DsrReleaseAsset $policy.repo $tag ($asset + '.minisig') $signature $inventory -MaximumBytes 65536
                Assert-DsrSignature $payload $signature $policy.public_key
                $signatureHash = (Get-DsrFileEvidence $signature).sha256
            }
            $receipt = [ordered]@{}
            foreach ($name in $binding.Keys) { $receipt[$name] = $binding[$name] }
            $receipt.checksum_file = $checksumName
            $receipt.sha256 = $expected
            $receipt.size_bytes = $evidence.size_bytes
            $receipt.signature_sha256 = $signatureHash
            Write-DsrNewTextFile ([IO.Path]::Combine($download, 'cache.json')) ($receipt | ConvertTo-Json -Compress)
            $null = Get-DsrCacheReceipt $download $binding $policy.public_key
            try { [IO.Directory]::Move($download, $cache) }
            catch [IO.IOException] {
                if (-not [IO.Directory]::Exists($cache)) { throw }
                $existing = Get-DsrCacheReceipt $cache $binding $policy.public_key
                if ($existing.sha256 -cne $receipt.sha256 -or $existing.size_bytes -ne $receipt.size_bytes) {
                    Stop-DsrInstall 'Concurrent download selected different release bytes' 2
                }
                $receipt = $existing
            }
        }
        if (-not $work) { $work = New-DsrPrivateDirectory ([IO.Path]::Combine($cacheRoot, ('.dsr-install-stage-' + [Guid]::NewGuid().ToString('N')))) }
        # Copy all proof into a private generation, then authenticate those
        # exact bytes. A cache pathname is never a reservation for extraction.
        $privateRelease = New-DsrPrivateDirectory ([IO.Path]::Combine($work, 'verified-release'))
        $proofNames = @('cache.json', $asset, $receipt.checksum_file)
        if ($policy.public_key) { $proofNames += ($asset + '.minisig') }
        foreach ($name in $proofNames) {
            Copy-DsrNewFile ([IO.Path]::Combine($cache, $name)) ([IO.Path]::Combine($privateRelease, $name))
        }
        $copied = Get-DsrCacheReceipt $privateRelease $binding $policy.public_key
        if ($copied.sha256 -cne $receipt.sha256 -or $copied.size_bytes -ne $receipt.size_bytes) {
            Stop-DsrInstall 'Cached release changed while its private copy was prepared' 7
        }
        $payload = [IO.Path]::Combine($privateRelease, $asset)
        $expanded = [IO.Path]::Combine($work, 'expanded')
        Expand-DsrPayload $payload $selection $platform $expanded
        # Recheck all original proof after extraction and before the first
        # destination write; an earlier successful hash is not a reservation.
        $null = Get-DsrCacheReceipt $privateRelease $binding $policy.public_key
        Write-DsrInstallVerbose 'Checksum, configured signature, archive and executable admission completed'
        if ($freshnessRequested) {
            # Verification is complete before any source decision. A stale
            # release cannot turn bad signature/archive/PE bytes into consent.
            $freshness = Get-DsrReleaseFreshness $policy.repo $tag ([int]$SourceIfStale) $work
            if ($freshness.status -ceq 'stale') {
                Write-DsrInstallLog ('Release ' + $tag + ' is ' + $freshness.commits_behind + ' commits behind the observed default branch')
                $retainSourceWork = $true
                $result = Install-DsrSourceFamily $policy $selection $platform $freshness.head_commit $work $SourceTimeout $cacheRoot $prefixPath $transactionIdentity -Yes:$Yes
                $retainSourceWork = $false
                $result.freshness = $freshness
                if ($Json) { [Console]::Out.WriteLine(($result | ConvertTo-Json -Depth 12 -Compress)) }
                else { [Console]::Out.WriteLine($result.path) }
                return 0
            }
            if ($freshness.status -ceq 'unknown') { Write-DsrInstallLog 'Freshness unknown; keeping the verified release' }
            else { Write-DsrInstallVerbose 'Latest release is within the requested commit-distance threshold' }
        }
        $installed = Install-DsrExecutableFamily $expanded $prefixPath $selection.binaries $transactionIdentity -Yes:$Yes
        $primary = $policy.binary_name
        if (-not $primary.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase)) { $primary += '.exe' }
        $primaryRow = @($installed | Where-Object { $_.name.Equals($primary, [StringComparison]::OrdinalIgnoreCase) })[0]
        $result = @{ tool = $tool; repository = $policy.repo; status = 'success'; version = $tag; platform = $platform;
            target_triple = $selection.target_triple; path = $primaryRow.path; binaries = @($installed);
            cache = @{ path = $cache; offline = [bool]$Offline }; signature_verified = [bool]$policy.public_key; exit_code = 0 }
        if ($null -ne $freshness) { $result.freshness = $freshness }
        Write-DsrInstallLog ('Installed ' + $tool + ' ' + $tag + ' (' + $installed.Count + ' executable(s))')
        if ($Json) { [Console]::Out.WriteLine(($result | ConvertTo-Json -Depth 12 -Compress)) }
        else { [Console]::Out.WriteLine($primaryRow.path) }
        return 0
    } catch {
        $failure = $_.Exception
        if ($fallbackReference) {
            # Only classified release acquisition above selects this path.
            # Never reuse its exception after compilation starts: source or
            # installation failure is final and retains its own diagnostics.
            try {
                $sourceWork = New-DsrPrivateDirectory ([IO.Path]::Combine($work, 'source-fallback'))
                $retainSourceWork = $true
                Write-DsrInstallLog ('Release acquisition unavailable; using permitted source fallback at ' + $fallbackReference)
                $result = Install-DsrSourceFamily $policy $selection $platform $fallbackReference $sourceWork $SourceTimeout $cacheRoot $prefixPath $transactionIdentity -Yes:$Yes
                $result.source_fallback = @{ reason = 'release_unavailable'; stage = $fallbackStage;
                    requested_ref = $fallbackReference; release_version = $fallbackVersion }
                $retainSourceWork = $false
                if ($Json) { [Console]::Out.WriteLine(($result | ConvertTo-Json -Depth 12 -Compress)) }
                else { [Console]::Out.WriteLine($result.path) }
                return 0
            } catch { $failure = $_.Exception }
        }
        $code = 7
        if ($failure.Data.Contains('DsrExitCode')) { $code = [int]$failure.Data['DsrExitCode'] }
        Write-DsrInstallLog $failure.Message
        if ($Json) {
            $result = @{ tool = $tool; status = 'error'; error = $failure.Message; exit_code = $code }
            if ($retainSourceWork -and $work) { $result.source_diagnostics = $work }
            if ($null -ne $freshness) { $result.freshness = $freshness }
            if ($fallbackReference) {
                $result.source_fallback = @{ reason = 'release_unavailable'; stage = $fallbackStage;
                    requested_ref = $fallbackReference; release_version = $fallbackVersion }
            }
            [Console]::Out.WriteLine(($result | ConvertTo-Json -Compress))
        }
        return $code
    } finally {
        if ($work) {
            if ($retainSourceWork) { Write-DsrInstallLog ('Source build diagnostics retained: ' + $work) }
            else {
                try { Remove-DsrPrivateTree $work }
                catch { Write-DsrInstallLog ('Private staging retained for inspection: ' + $work) }
            }
        }
    }
}

# DSR_WINDOWS_INSTALL_DISPATCH: tests replace only host/HTTP boundaries before this call.
exit (Invoke-DsrWindowsInstaller @PSBoundParameters)
